export default JSON.parse('{"work":{"id":"wu-zi","schoolId":"military","title":"《吳子》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["wu-zi_ch-1","wu-zi_ch-2","wu-zi_ch-3","wu-zi_ch-4","wu-zi_ch-5","wu-zi_ch-6"],"totalChars":5906,"subtitle":"吳起"},"chapters":[{"id":"wu-zi_ch-1","workId":"wu-zi","order":1,"title":"圖國","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-1_p-1","wu-zi_ch-1_p-2","wu-zi_ch-1_p-3","wu-zi_ch-1_p-4","wu-zi_ch-1_p-5","wu-zi_ch-1_p-6","wu-zi_ch-1_p-7","wu-zi_ch-1_p-8"],"tags":[]},{"id":"wu-zi_ch-2","workId":"wu-zi","order":2,"title":"料敵","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-2_p-1","wu-zi_ch-2_p-2","wu-zi_ch-2_p-3","wu-zi_ch-2_p-4"],"tags":[]},{"id":"wu-zi_ch-3","workId":"wu-zi","order":3,"title":"治兵","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-3_p-1","wu-zi_ch-3_p-2","wu-zi_ch-3_p-3","wu-zi_ch-3_p-4","wu-zi_ch-3_p-5","wu-zi_ch-3_p-6","wu-zi_ch-3_p-7","wu-zi_ch-3_p-8"],"tags":[]},{"id":"wu-zi_ch-4","workId":"wu-zi","order":4,"title":"論將","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-4_p-1","wu-zi_ch-4_p-2","wu-zi_ch-4_p-3","wu-zi_ch-4_p-4","wu-zi_ch-4_p-5"],"tags":[]},{"id":"wu-zi_ch-5","workId":"wu-zi","order":5,"title":"應變","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-5_p-1","wu-zi_ch-5_p-2","wu-zi_ch-5_p-3","wu-zi_ch-5_p-4","wu-zi_ch-5_p-5","wu-zi_ch-5_p-6","wu-zi_ch-5_p-7","wu-zi_ch-5_p-8","wu-zi_ch-5_p-9","wu-zi_ch-5_p-10","wu-zi_ch-5_p-11"],"tags":[]},{"id":"wu-zi_ch-6","workId":"wu-zi","order":6,"title":"勵士","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-6_p-1","wu-zi_ch-6_p-2","wu-zi_ch-6_p-3","wu-zi_ch-6_p-4","wu-zi_ch-6_p-5","wu-zi_ch-6_p-6"],"tags":[]}],"passages":[{"id":"wu-zi_ch-1_p-1","chapterId":"wu-zi_ch-1","order":1,"canonicalText":"吳起儒服以兵機見魏文侯。文侯曰：「寡人不好軍旅之事。」起曰：「臣以見佔隱，以往察來，主君何言與心違？今君四時使斬離皮革，掩以朱漆，畫以丹青，爍以犀象。冬日衣之則不溫，夏日衣之則不涼。為長戟二丈四尺，短戟一丈二尺。革車奄戶，縵輪籠轂，觀之於目則不麗，乘之以田則不輕，不識主君安用此也？若以備進戰退守，而不求能用者，譬猶伏雞之搏狸，乳犬之犯虎，雖有鬥心，隨之死矣。昔承桑氏之君，修德廢武，以滅其國。有扈氏之君，恃眾好勇，以喪其社稷。明主鑒茲，必內修文德，外治武備。故當敵而不進，無逮於義矣；僵屍而哀之，無逮於仁矣。」於是文侯身自布席，夫人捧觴，醮吳起於廟，立為大將，守西河。與諸侯大戰七十六，全勝六十四，餘則鈞解。闢土四面，拓地千里，皆起之功也。","sentenceIds":["wu-zi_ch-1_p-1_s-1","wu-zi_ch-1_p-1_s-2","wu-zi_ch-1_p-1_s-3","wu-zi_ch-1_p-1_s-4","wu-zi_ch-1_p-1_s-5","wu-zi_ch-1_p-1_s-6","wu-zi_ch-1_p-1_s-7","wu-zi_ch-1_p-1_s-8","wu-zi_ch-1_p-1_s-9","wu-zi_ch-1_p-1_s-10","wu-zi_ch-1_p-1_s-11","wu-zi_ch-1_p-1_s-12","wu-zi_ch-1_p-1_s-13","wu-zi_ch-1_p-1_s-14","wu-zi_ch-1_p-1_s-15","wu-zi_ch-1_p-1_s-16"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳起身穿儒服，以精通兵法機謀面見魏文侯。文侯說：「我不喜歡軍事打仗之事。」吳起說：「臣能從顯露的現象推測隱微的事物，從過去的經歷察知未來的發展，主君說的話為什麼與心裡想的不一樣呢？如今您一年四季讓人裁切皮革製造鎧甲，塗上朱漆，繪飾彩畫，鑲嵌犀角象牙。冬天穿它並不溫暖，夏天穿它並不涼爽。又製造長達二丈四尺的長戟，和一丈二尺的短戟。用皮革包裹戰車的車戶，蒙上車輪、籠罩轂心，論觀賞並不美觀，駕乘去打獵也不輕便，臣實在不明白主君要這些東西有何用處？如果這是用來準備進攻戰鬥或後退防守，卻不尋求懂得出兵作戰的人才，就好比抱窩的母雞去搏擊野貓，哺乳的母狗去侵犯猛虎，雖然有鬥志，接著就只有死亡了。從前承桑氏的國君，專修文德而廢棄武備，結果國家遭到滅亡；有扈氏的國君，仗著人口眾多、逞勇好鬥，結果喪失了社稷。明智的君主引此為鑑，必定在內修明文德，在外整備武備。因此面對敵人卻不敢進擊，就稱不上義；等到戰死積屍纔去哀悼，就稱不上仁了。」於是魏文侯親自為他鋪設席位，夫人親捧酒杯，在宗廟中為吳起舉行祭酒授任之禮，立他為大將，鎮守西河地區。吳起後來與各諸侯國大戰七十六次，全勝六十四次，其餘幾次也是不相上下。魏國向四面開疆拓土千里，都是吳起的功勞。","analysis":"【主題與背景】\\\\n本段記載吳起以儒生裝束面見魏文侯，直指魏文侯表面聲稱不喜軍旅，實則暗中擴充武備但欠缺戰略人才的矛盾，進而論述文德與武備兼修的重要性。\\\\n\\\\n【詞義與名物】\\\\n「以見佔隱」：透過表面現象推斷隱微本質。「承桑氏」、「有扈氏」：古代因偏廢文德或武備而滅亡的歷史反面教材。「醮」：古代於宗廟中授任大將的隆重禮儀。\\\\n\\\\n【兵家戰略】\\\\n吳起指出「內修文德，外治武備」是國家安全的雙軌基礎。光有精良裝備而無懂兵善戰之將，如「伏雞搏狸」必然自取滅亡；兵家思想在此呈現出政治文德與軍事武備不可偏廢的辯證關係。"}},{"id":"wu-zi_ch-1_p-2","chapterId":"wu-zi_ch-1","order":2,"canonicalText":"吳子曰：「昔之圖國家者，必先教百姓而親萬民。有四不和：不和於國，不可以出軍；不和於軍，不可以出陳；不和於陳，不可以進戰；不和於戰，不可以決勝。是以有道之主，將用其民，先和而造大事。不敢信其私謀，必告於祖廟，啟於元龜，參之天時，吉乃後舉。民知君之愛其命，惜其死，若此之至，而與之臨難，則士以盡死為榮，退生為辱矣。」","sentenceIds":["wu-zi_ch-1_p-2_s-1","wu-zi_ch-1_p-2_s-2","wu-zi_ch-1_p-2_s-3","wu-zi_ch-1_p-2_s-4","wu-zi_ch-1_p-2_s-5","wu-zi_ch-1_p-2_s-6","wu-zi_ch-1_p-2_s-7","wu-zi_ch-1_p-2_s-8","wu-zi_ch-1_p-2_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「從前謀劃國家大業的人，必定先教化百姓、親近萬民。作戰有四種『不和』：國內人心不和，不可出動軍隊；軍隊內部不和，不可擺開陣勢；陣勢之間不和，不可推進作戰；戰鬥協調不和，不可決求勝負。因此有道的君主想要動用百姓時，必定先做到和諧纔去開創大事。他們不敢過分自信於私人的謀劃，必定先稟告祖廟，開卜大龜，參考天時運勢，獲得吉兆之後才採取行動。百姓知道君主如此關愛他們的生命、痛惜他們的死亡，達到了這種至誠的地步，此時與百姓共同面對危難，士兵就會以戰死沙場為榮，以苟活後退為辱了。」","analysis":"【主題與背景】\\\\n本段闡述「以和為本」與「愛民惜死」的政治軍事哲學，強調軍事勝利建立在國內團結、軍心一致與民心歸順的基礎上。\\\\n\\\\n【詞義與名物】\\\\n「四不和」：國不和、軍不和、陳不和、戰不和，由巨觀政局至微觀戰術層層遞進。「元龜」：古代用於國家重大決策卜筮的大龜。\\\\n\\\\n【兵家戰略】\\\\n吳起提出「先和而造大事」，強調軍隊的戰鬥力來源於民心。君主若能展現對士兵生命的極致愛護，士兵便能產生同仇敵儾、視死如歸的強大凝聚力。"}},{"id":"wu-zi_ch-1_p-3","chapterId":"wu-zi_ch-1","order":3,"canonicalText":"吳子曰：「夫道者，所以反本復始。義者，所以行事立功。謀者，所以違害就利。要者，所以保業守成。若行不合道，舉不合義，而處大居貴，患必及之。是以聖人綏之以道，理之以義，動之以禮，撫之以仁。此四德者，修之則興，廢之則衰。故成湯討桀而夏民喜悅，周武伐紂而殷人不非。舉順天人，故能然矣。」","sentenceIds":["wu-zi_ch-1_p-3_s-1","wu-zi_ch-1_p-3_s-2","wu-zi_ch-1_p-3_s-3","wu-zi_ch-1_p-3_s-4","wu-zi_ch-1_p-3_s-5","wu-zi_ch-1_p-3_s-6","wu-zi_ch-1_p-3_s-7","wu-zi_ch-1_p-3_s-8","wu-zi_ch-1_p-3_s-9","wu-zi_ch-1_p-3_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「所謂『道』，是用來返璞歸真、順應根本的；『義』，是用來推行事務、建立功業的；『謀』，是用來避開危害、趨向有利的；『要』，是用來鞏固家業、守住成效的。如果行為不合於道，舉動不合於義，卻身處高位尊貴之處，禍患必定會降臨到身上。因此聖人用『道』安撫萬民，用『義』治理事務，用『禮』規範行動，用『仁』關懷體恤。這四種美德，修明它國家就會興盛，廢棄它國家就會衰亡。所以商湯討伐夏桀而夏國百姓歡喜，周武王討伐商紂而商朝人民不加非議，正是因為他們的舉措順應了天理與人心啊。」","analysis":"【主題與背景】\\\\n本段提出道、義、謀、要四項立國根本，並結合道、義、禮、仁四德，論證正義之師順應天人的合法性。\\\\n\\\\n【詞義與名物】\\\\n「反本復始」：回到天理人情的根本。「成湯討桀」、「周武伐紂」：古代順應天命人心的革命正義範例。\\\\n\\\\n【兵家戰略】\\\\n吳起將兵家戰略納入儒道政治倫理架構中，認為「舉順天人」是戰爭獲得政治合法性與戰術勝利的終極保證。"}},{"id":"wu-zi_ch-1_p-4","chapterId":"wu-zi_ch-1","order":4,"canonicalText":"吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。夫人有恥，在大足以戰，在小足以守矣。然戰勝易，守勝難。故曰：天下戰國，五勝者禍，四勝者弊，三勝者霸，二勝者王，一勝者帝。是以數勝得天下者稀，以亡者眾。」","sentenceIds":["wu-zi_ch-1_p-4_s-1","wu-zi_ch-1_p-4_s-2","wu-zi_ch-1_p-4_s-3","wu-zi_ch-1_p-4_s-4","wu-zi_ch-1_p-4_s-5","wu-zi_ch-1_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是治理國家與統率軍隊，必定要用『禮』來教化，用『義』來鼓勵，使士兵產生羞恥心。人只要有了羞恥心，兵力多時足可以用於進攻戰鬥，兵力少時足可以用於堅守防禦。然而戰勝敵人容易，鞏固勝利成果卻困難。所以說：天下從事戰爭的國家，靠武力獲得五次勝利的會招致禍害，四次勝利的會疲弊衰落，三次勝利的可以成就霸業，兩次勝利的可以成就王業，一次勝利就能平定天下的則可成就帝業。因此靠多次打勝仗而取得天下的極為稀少，因而導致滅亡的反而極多。」","analysis":"【主題與背景】\\\\n本段深刻剖析了戰爭頻率與國家興衰的關係，提出著名的「五勝者禍，一勝者帝」戰略警示。\\\\n\\\\n【詞義與名物】\\\\n「有恥」：具有榮辱觀與道德恥辱感。「守勝」：戰勝之後如何鞏固戰果、養息國力。\\\\n\\\\n【兵家戰略】\\\\n吳起警惕過度用兵與盲目追求軍事勝利的副作用。頻繁戰爭會窮兵黷武、耗盡國力（五勝者禍），唯有結合強大政治整合力、少戰而大勝者才能實現長治久安。"}},{"id":"wu-zi_ch-1_p-5","chapterId":"wu-zi_ch-1","order":5,"canonicalText":"吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。」","sentenceIds":["wu-zi_ch-1_p-5_s-1","wu-zi_ch-1_p-5_s-2","wu-zi_ch-1_p-5_s-3","wu-zi_ch-1_p-5_s-4","wu-zi_ch-1_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是戰爭爆發的原因有五種：一是爭奪名聲，二是爭奪利益，三是積怨深重，四是國家內亂，五是遇到饑荒。戰爭的性質名稱也有五種：一是義兵，二是強兵，三是剛兵，四是暴兵，五是逆兵。禁止暴虐、救援動亂稱為『義兵』；仗著兵多去討伐稱為『強兵』；因一時發怒而興師稱為『剛兵』；背棄禮義、貪圖利益稱為『暴兵』；國家混亂、人民疲憊卻盲目動員軍隊稱為『逆兵』。應對這五種性質的軍隊，各有不同的原則：對付義兵必須用禮義折服，對付強兵必須用謙遜應對，對付剛兵必須用外交言語化解，對付暴兵必須用奇謀詐術剋制，對付逆兵則必須用權謀機變制勝。」","analysis":"【主題與背景】\\\\n本段對戰爭的起因與性質進行系統分類，並方針性地提出針對不同類型敵軍的剋制戰略。\\\\n\\\\n【詞義與名物】\\\\n「五兵」：義兵、強兵、剛兵、暴兵、逆兵。「五服」：禮服、謙服、辭服、詐服、權服。\\\\n\\\\n【兵家戰略】\\\\n吳起強調「因敵施策」，區分戰爭的道德正當性與力量對比，主張對於正義或強大的對手不可以硬碰硬，對於暴逆之敵則需靈活採取權謀與奇計。"}},{"id":"wu-zi_ch-1_p-6","chapterId":"wu-zi_ch-1","order":6,"canonicalText":"武侯問曰：「願聞治兵、料人、固國之道。」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。昔齊桓募士五萬，以霸諸侯。晉文召為前行四萬，以獲其志。秦繆置陷陳三萬，以服鄰敵。故強國之君，必料其民。民有膽勇氣力者，聚為一卒。樂以進戰效力、以顯其忠勇者，聚為一卒。能踰高超遠、輕足善走者，聚為一卒。王臣失位而欲見功於上者，聚為一卒。棄城去守、欲除其醜者，聚為一卒。此五者，軍之練銳也。有此三千人，內出可以決圍，外入可以屠城矣。」","sentenceIds":["wu-zi_ch-1_p-6_s-1","wu-zi_ch-1_p-6_s-2","wu-zi_ch-1_p-6_s-3","wu-zi_ch-1_p-6_s-4","wu-zi_ch-1_p-6_s-5","wu-zi_ch-1_p-6_s-6","wu-zi_ch-1_p-6_s-7","wu-zi_ch-1_p-6_s-8","wu-zi_ch-1_p-6_s-9","wu-zi_ch-1_p-6_s-10","wu-zi_ch-1_p-6_s-11","wu-zi_ch-1_p-6_s-12","wu-zi_ch-1_p-6_s-13","wu-zi_ch-1_p-6_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「我想聽聽治理軍隊、考量人才、鞏固國家的道理。」吳起回答說：「古代明智的君王，必定嚴謹遵守君臣禮節，整飭上下儀制，安撫聚集官吏百姓，順應風俗進行教化，選拔招募優秀人才，以防備意料之外的變故。從前齊桓公招募精兵五萬，因而稱霸諸候；晉文公召集四萬精銳作為前鋒，因而實現志向；秦穆公設置陷陣勇士三萬，因而征服鄰敵。所以強國的君主，必定審察考量自己的百姓。百姓中膽勇過人、體力強健的，編聚為一隊；樂於向前戰鬥效力、展現忠勇的，編聚為一隊；能夠攀高跳遠、腳步輕快善於奔跑的，編聚為一隊；王臣失去官位而急於向上立功的，編聚為一隊；曾棄城失守而想要洗刷羞恥的，編聚為一隊。這五類人，是軍隊中最精銳的骨幹。擁有這樣的精銳三千人，由內突圍可以突破重圍，由外進攻可以攻克敵城。」","analysis":"【主題與背景】\\\\n本段論述精兵政策與兵員分類編組的戰術思想，主張根據士兵的心理特徵與體能專長進行針對性編排。\\\\n\\\\n【詞義與名物】\\\\n「料人」：審察、評估民力與個體特徵。「練銳」：經過嚴格篩選與針對性組合的精銳特別行動部隊。\\\\n\\\\n【兵家戰略】\\\\n吳起開創了軍隊「特種選拔與專業化編組」的先河。將具有同類心理動機（如洗刷羞恥、求功心切）或身體特長者集中編隊，能發揮遠超普通部隊的爆發力與突擊效能。"}},{"id":"wu-zi_ch-1_p-7","chapterId":"wu-zi_ch-1","order":7,"canonicalText":"武侯問曰：「願聞陳必定、守必固、戰必勝之道。」起對曰：「立見且可，豈直聞乎！君能使賢者居上，不肖者處下，則陳已定矣。民安其田宅，親其有司，則守已固矣。百姓皆是吾君而非鄰國，則戰已勝矣。」","sentenceIds":["wu-zi_ch-1_p-7_s-1","wu-zi_ch-1_p-7_s-2","wu-zi_ch-1_p-7_s-3","wu-zi_ch-1_p-7_s-4","wu-zi_ch-1_p-7_s-5","wu-zi_ch-1_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「我想聽聽陣勢必定穩定、防守必定堅固、作戰必定勝利的道理。」吳起回答說：「這立刻就能看到成效，豈止是聽聽而已呢！主君如果能讓有德有才的人身居高位，讓無德無才的人處於下位，那麼陣勢就已經穩定了；百姓安居於他們的田宅，親近他們的官吏，那麼防守就已經堅固了；百姓都認同贊許我們自己的君主，而指責非難鄰國，那麼戰鬥就已經勝利了。」","analysis":"【主題與背景】\\\\n本段以極具說服力的對答，將陣勢、防守、作戰這三項軍事指標，直接歸結為用人、民生與政治認同。\\\\n\\\\n【詞義與名物】\\\\n「陳必定、守必固、戰必勝」：傳統軍事作戰的三大核心目標。「有司」：管理基層事務的官員。\\\\n\\\\n【兵家戰略】\\\\n吳起展現了「兵政合一」的最高智慧：軍事上的勝負在戰場之外就已決定。任人唯賢則指揮層穩定，基層安居則防守穩固，人心歸附則戰無不勝。"}},{"id":"wu-zi_ch-1_p-8","chapterId":"wu-zi_ch-1","order":8,"canonicalText":"武侯嘗謀事，群臣莫能及，罷朝而有喜色。起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。申公問曰：『君有憂色，何也？』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。今寡人不才，而群臣莫及者，楚國其殆矣。』此楚莊王之所憂，而君說之，臣竊懼矣。」於是武侯有慚色。","sentenceIds":["wu-zi_ch-1_p-8_s-1","wu-zi_ch-1_p-8_s-2","wu-zi_ch-1_p-8_s-3","wu-zi_ch-1_p-8_s-4","wu-zi_ch-1_p-8_s-5","wu-zi_ch-1_p-8_s-6","wu-zi_ch-1_p-8_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯曾經與群臣商議國家大事，沒有一個大臣的見識能比得上他，退朝後武侯面露喜色。吳起走上前說：「從前楚莊王與群臣商議國事，群臣的見解都比不上他，退朝後楚莊王卻面露憂愁。申公問他：『君王面帶憂色，是為什麼呢？』楚莊王說：『我聽說，世上從來不缺聖人，國家也不會缺乏賢才。能夠找到可以做自己老師的人，就能成就王業；能找到可以做自己朋友的人，就能成就霸業。現在我這麼沒有才能，群臣卻連我都比不上，楚國恐怕要危險了。』這正是楚莊王所擔憂的事，而您卻為此感到高興，我私下為您感到害怕。」魏武侯聽了，臉上露出了慚愧的神色。","analysis":"【主題與背景】\\n本段記載了吳起直言勸諫魏武侯的故事。在戰國初期，魏國正處於霸業的上升期，吳起藉由楚莊王的歷史典故，提醒君王必須保持謙遜並積極求賢。\\n\\n【詞義與名物】\\n「王」與「霸」：王道指以德服人，霸道指以力服人。在此代表著國家強盛的不同層次。\\n\\n【兵家戰略】\\n兵家雖然重視戰術，但更明白國家戰略的核心在於人才。吳起指出，君王如果因為群臣不如自己而沾沾自喜，將導致國家陷入無人能諫、無人可用的危險境地。這體現了「將道」中對領導者品格的極高要求。"}},{"id":"wu-zi_ch-2_p-1","chapterId":"wu-zi_ch-2","order":1,"canonicalText":"武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。六國兵四守，勢甚不便，憂此奈何？」起對曰：「夫安國家之道，先戒為寶。今君已戒，禍其遠矣。臣請論六國之俗：夫齊陳重而不堅，秦陳散而自鬭，楚陳整而不久，燕陳守而不走，三晉陳治而不用。夫齊性剛，其國富，君臣驕奢而簡於細民，其政寬而祿不均，一陳兩心，前重後輕，故重而不堅。擊此之道，必三分之，獵其左右，脅而從之，其陳可壞。秦性強，其地險，其政嚴，其賞罰信，其人不讓，皆有鬭心，故散而自戰。擊此之道，必先示之以利而引去之，士貪於得而離其將，乘乖獵散，設伏投機，其將可取。楚性弱，其地廣，其政騷，其民疲，故整而不久。擊此之道，襲亂其屯，先奪其氣。輕進速退，弊而勞之，勿與戰爭，其軍可敗。燕性愨，其民慎，好勇義，寡詐謀，故守而不走。擊此之道，觸而迫之，陵而遠之，馳而後之，則上疑而下懼，謹我車騎必避之路，其將可虜。三晉者，中國也，其性和，其政平，其民疲於戰，習於兵，輕其將，薄其祿，士無死志，故治而不用。擊此之道，阻陳而壓之，眾來則拒之，去則追之，以倦其師。此其勢也。然則一軍之中，必有虎賁之士；力輕扛鼎，足輕戎馬，搴旗斬將，必有能者。若此之等，選而別之，愛而貴之，是謂軍命。其有工用五兵、材力健疾、志在吞敵者，必加其爵列，可以決勝。厚其父母妻子，勸賞畏罰，此堅陳之士，可與持久。能審料此，可以擊倍。」武侯曰：「善。」","sentenceIds":["wu-zi_ch-2_p-1_s-1","wu-zi_ch-2_p-1_s-2","wu-zi_ch-2_p-1_s-3","wu-zi_ch-2_p-1_s-4","wu-zi_ch-2_p-1_s-5","wu-zi_ch-2_p-1_s-6","wu-zi_ch-2_p-1_s-7","wu-zi_ch-2_p-1_s-8","wu-zi_ch-2_p-1_s-9","wu-zi_ch-2_p-1_s-10","wu-zi_ch-2_p-1_s-11","wu-zi_ch-2_p-1_s-12","wu-zi_ch-2_p-1_s-13","wu-zi_ch-2_p-1_s-14","wu-zi_ch-2_p-1_s-15","wu-zi_ch-2_p-1_s-16","wu-zi_ch-2_p-1_s-17","wu-zi_ch-2_p-1_s-18","wu-zi_ch-2_p-1_s-19","wu-zi_ch-2_p-1_s-20","wu-zi_ch-2_p-1_s-21","wu-zi_ch-2_p-1_s-22","wu-zi_ch-2_p-1_s-23","wu-zi_ch-2_p-1_s-24","wu-zi_ch-2_p-1_s-25"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯對吳起說：「如今秦國在西面威脅我們，楚國在南面包圍我們，趙國在北面直衝我們，齊國在東面逼近我們，燕國在後面切斷退路，韓國在前面扼守要衝。六國大軍環伺四方，形勢非常不利，我為此憂慮該怎麼辦？」吳起回答說：「安邦定國之道，以預先警惕最為寶貴。如今主君已經有了戒備，禍害自然就遠離了。請允許臣論述六國的風俗特徵：齊國的軍陣看似笨重卻不堅固；秦國的軍陣分散而各自為戰；楚國的軍陣整齊卻不能持久；燕國的軍陣固守卻不敢主動出擊；三晉（韓、趙、魏）的軍陣治理整齊卻缺乏戰鬥意志。齊人性格剛強，國家富有，君臣驕奢而輕視平民，政治寬鬆而奉祿不均，同一個軍陣卻君臣異心，前重後輕，所以笨重而不堅固。攻擊齊軍的方法，必須將軍隊一分為三，騷擾襲擊其左右兩翼，脅迫跟隨，其軍陣即可破壞。秦人性格強悍，地形險要，政治嚴酷，賞罰誠信，人們互不謙讓而富有鬥志，所以分散各自為戰。攻擊秦軍的方法，必須先展示利益將其引開，士兵貪圖利益就會脫離將領，乘其脫節分散、設下伏兵抓住時機，其將領即可擒獲。楚人性格懦弱，土地廣袤，政令紛擾，百姓疲憊，所以陣勢整齊卻不能持久。攻擊楚軍的方法，是襲擊騷擾其營屯，先摧毀其士氣，輕快進擊快速撤退，使其疲憊不堪，不與其正面決戰，其軍隊即可擊敗。燕人性格誠實，民風謹慎，喜好勇義，缺少詐謀，所以堅守而不退跑。攻擊燕軍的方法，是衝擊逼迫，凌駕遠繞，快速奔襲其後方，使其上層猜疑、下層恐懼，嚴密防範我方車騎留出敵必避之路，其將領即可俘獲。三晉位於中原，民風溫和，政治平穩，人民因頻繁戰爭而疲憊，雖熟悉軍事，卻輕視將領、奉祿薄少，士兵沒有必死意志，所以軍陣整齊卻沒有戰鬥力。攻擊三晉軍隊的方法，是阻擋其軍陣並施加壓力，敵大軍前來則拒守，退去則追擊，使其軍隊疲憊。這就是各國的形勢特點。然而在一支軍隊中，必定有勇猛如虎的勇士，力能扛鼎、足能追奔馬，能砍旗斬將者，必定有這種能人。像這樣的人，挑選出來另外編組，愛護並尊貴他們，這叫做軍隊的命脈。如果有精通五種兵器、體力健捷、志在吞滅敵人者，一定要提升他們的爵位，可以靠他們決勝。厚待他們的父母妻子，用賞賜鼓勵、用刑罰震懾，這是堅固軍陣的士卒，可以與敵人持久對抗。能夠審慎考量這些，就可以打敗倍數於己的敵人。」武侯說：「講得好！」","analysis":"【主題與背景】\\\\n本段是中國古代戰略地理與各國兵風民俗的經典剖析。吳起針對戰國初期魏國被秦、楚、趙、齊、燕、韓六國環伺的嚴峻局勢，逐一拆解六國軍隊的性格、陣勢特點與相應的戰術破法。\\\\n\\\\n【詞義與名物】\\\\n「重而不堅、散而自鬭、整而不久、守而不走、治而不用」：吳起對齊、秦、楚、燕、三晉軍事特徵的五大名評。「虎賁之士」：軍中極其勇猛精銳的特別突擊隊。\\\\n\\\\n【兵家戰略】\\\\n吳起展現了「知己知彼、因敵制勝」的頂級戰略戰術思維。不抽象論戰，而是將政治、風俗、性格、地形與戰術有機結合，強調根據對手的具體弱點採用分化、利誘、疲敵、心理威嚇等不同戰術。"}},{"id":"wu-zi_ch-2_p-2","chapterId":"wu-zi_ch-2","order":2,"canonicalText":"吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；二曰盛夏炎熱，晏興無間，行驅飢渴，務於取遠；三曰師既淹久，糧食無有，百姓怨怒，祅祥數起，上不能止；四曰軍資既竭，薪芻既寡，天多陰雨，欲掠無所；五曰徒眾不多，水地不利，人馬疾疫，四鄰不至；六曰道遠日暮，士眾勞懼，倦而未食，解甲而息；七曰將薄吏輕，士卒不固，三軍數驚，師徒無助；八曰陳而未定，舍而未畢，行阪涉險，半隱半出。諸如此者，擊之勿疑。有不佔而避之者六：一曰土地廣大，人民富眾；二曰上愛其下，惠施流佈；三曰賞信刑察，發必得時；四曰陳功居列，任賢使能；五曰師徒之眾，兵甲之精；六曰四鄰之助，大國之援。凡此不如敵人，避之勿疑。所謂見可而進，知難而退也。」","sentenceIds":["wu-zi_ch-2_p-2_s-1","wu-zi_ch-2_p-2_s-2","wu-zi_ch-2_p-2_s-3","wu-zi_ch-2_p-2_s-4","wu-zi_ch-2_p-2_s-5","wu-zi_ch-2_p-2_s-6","wu-zi_ch-2_p-2_s-7","wu-zi_ch-2_p-2_s-8","wu-zi_ch-2_p-2_s-9","wu-zi_ch-2_p-2_s-10","wu-zi_ch-2_p-2_s-11","wu-zi_ch-2_p-2_s-12","wu-zi_ch-2_p-2_s-13","wu-zi_ch-2_p-2_s-14","wu-zi_ch-2_p-2_s-15","wu-zi_ch-2_p-2_s-16","wu-zi_ch-2_p-2_s-17","wu-zi_ch-2_p-2_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是考量敵人，有八種情況不必占卜就可以與之交戰：一是大風嚴寒，敵人早起拔營移屯，砍伐樹木渡水，不避艱難；二是盛夏炎熱，敵軍起得晚且無間隔休息，急行軍飢渴難耐，一心遠行；三是敵軍出征已久，糧食斷絕，百姓怨恨怒罵，凶兆頻起，上層無法制止；四是軍用物資耗盡，柴草匱乏，天多陰雨，想搶劫也無處搶；五是兵眾不多，水土不利，人馬染病，四鄰救援不到；六是道路遙遠日落西山，士眾疲憊恐懼，飢腸轆轆卻未吃飯，解開鎧甲休息；七是將領平庸官吏輕浮，士卒人心不固，三軍屢次驚恐，軍隊孤立無援；八是列陣未定，宿營未畢，行經山坡過險，隊伍半隱半現。凡屬此類情況，果斷攻擊無須猶豫。有六種情況不必占卜就必須避開敵人：一是土地廣大，人口富庶；二是上層愛護下屬，恩惠廣泛流佈；三是賞賜誠信刑罰明察，出兵必合時宜；四是論功行賞按功排列，任人唯賢；五是軍隊數量眾多，武器裝備精良；六是四鄰鼎力相助，有大國為後援。凡在這些方面不如敵人，果斷避開無須猶豫。這就是所謂的『見可而進，知難而退』。」","analysis":"【主題與背景】\\\\n本段系統總結了八種「可擊之敵」與六種「不可擊（應避）之敵」的具體指標，是戰場情報評估與決策選擇的經典法則。\\\\n\\\\n【詞義與名物】\\\\n「八可擊、六應避」：基於天時、地理、糧餉、士氣、將領、政治六個維度的軍事實力評估體系。\\\\n\\\\n【兵家戰略】\\\\n吳起強調理性決策，反對迷信占卜。當敵人處於疲憊、困頓、混亂、將庸、陣腳未穩時應果斷主動出擊；而當敵人政治清明、民心團結、軍備精良時則應避其鋒芒。"}},{"id":"wu-zi_ch-2_p-3","chapterId":"wu-zi_ch-2","order":3,"canonicalText":"武侯問曰：「吾欲觀敵之外以知其內，察其進以知其止，以定勝負，可得聞乎？」起對曰：「敵人之來，蕩蕩無慮，旌旗煩亂，人馬數顧，一可擊十，必使無措。諸侯大會，君臣未和，溝壘未成，禁令未施，三軍匈匈，欲前不能，欲去不敢，以半擊倍，百戰不殆。」","sentenceIds":["wu-zi_ch-2_p-3_s-1","wu-zi_ch-2_p-3_s-2","wu-zi_ch-2_p-3_s-3","wu-zi_ch-2_p-3_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「察其進以」的情境，應當採取相應的具體對策，對於「以定勝負」的情境，應當採取相應的具體對策，對於「可得聞乎」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「百戰」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「百戰」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-2_p-4","chapterId":"wu-zi_ch-2","order":4,"canonicalText":"武侯問敵必可擊之道。起對曰：「用兵必須審敵虛實而趨其危。敵人遠來新至、行列未定可擊，既食未設備可擊，奔走可擊，勤勞可擊，未得地利可擊，失時不從可擊，旌旗亂動可擊，涉長道後行未息可擊，涉水半渡可擊，險道狹路可擊，陳數移動可擊，將離士卒可擊，心怖可擊。凡若此者，選銳衝之，分兵繼之，急擊勿疑。」","sentenceIds":["wu-zi_ch-2_p-4_s-1","wu-zi_ch-2_p-4_s-2","wu-zi_ch-2_p-4_s-3","wu-zi_ch-2_p-4_s-4","wu-zi_ch-2_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯詢問敵人必定可以攻擊的具體時機。吳起回答說：「用兵作戰必須審察敵人的虛實而奔向敵人的危難困境。敵人遠道而來初次到達、行列未定時可以攻擊；剛剛吃飯尚未設置防備時可以攻擊；奔波逃跑時可以攻擊；勞累疲憊時可以攻擊；未佔據有利地形時可以攻擊；錯失時機不合天時可以攻擊；旌旗混亂晃動時可以攻擊；經過長途跋涉隊尾未獲休息時可以攻擊；渡水渡到一半時可以攻擊；行經險道狹路時可以攻擊；軍陣頻繁移動時可以攻擊；將領脫離士卒時可以攻擊；內心恐懼時可以攻擊。凡遇到這類情況，挑選精銳部隊發起衝鋒，分出兵力後續跟進，迅速果斷發起攻擊，絕不猶豫。」","analysis":"【主題與背景】\\\\n本段詳盡列舉了十三種戰場上敵軍顯露致命漏洞的「必擊」時機與應對戰術。\\\\n\\\\n【詞義與名物】\\\\n「審虛實而趨其危」：審察敵人之虛實，專挑敵人最脆弱危險之處猛擊。「涉水半渡」：兵家傳統的「半渡而擊」經典時機。\\\\n\\\\n【兵家戰略】\\\\n吳起提倡極致的機動性與決斷力。只要敵軍處於狀態不穩、防禦鬆懈、地形不利或心理恐懼的瞬間，即應以精銳為先鋒迅速突擊，使敵人無法組織有效反擊。"}},{"id":"wu-zi_ch-3_p-1","chapterId":"wu-zi_ch-3","order":1,"canonicalText":"武侯問曰：「進兵之道何先？」起對曰：「先明四輕、二重、一信。」曰：「何謂也？」對曰：「使地輕馬，馬輕車，車輕人，人輕戰。明知陰陽，則地輕馬。芻秣以時，則馬輕車。膏鐧有餘，則車輕人。鋒銳甲堅，則人輕戰。進有重賞，退有重刑。行之以信。令制遠，此勝之主也。」","sentenceIds":["wu-zi_ch-3_p-1_s-1","wu-zi_ch-3_p-1_s-2","wu-zi_ch-3_p-1_s-3","wu-zi_ch-3_p-1_s-4","wu-zi_ch-3_p-1_s-5","wu-zi_ch-3_p-1_s-6","wu-zi_ch-3_p-1_s-7","wu-zi_ch-3_p-1_s-8","wu-zi_ch-3_p-1_s-9","wu-zi_ch-3_p-1_s-10","wu-zi_ch-3_p-1_s-11","wu-zi_ch-3_p-1_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「推進軍隊的途徑以什麼為優先？」吳起回答說：「首先要明確『四輕、二重、一信』。」武侯問：「這話是什麼意思呢？」回答說：「要做到地有利於馬（地輕馬），馬適於拉車（馬輕車），車便於載人（車輕人），人樂於作戰（人輕戰）。明白掌握陰陽氣候，地就能利於馬；按時餵養草料，馬就能適於拉車；車軸潤滑充沛，車就能便於載人；武器鋒利鎧甲堅固，人就能樂於作戰。前進有重賞，後退有重刑，貫徹實行貴在誠信。掌握好這些原則，就是戰勝敵人的主導因素。」","analysis":"【主題與背景】\\\\n本段提出著名的軍隊後勤裝備與士氣連鎖理論——「四輕二重一信」，將作戰準備拆解為人、車、馬、地、軍紀的系統工程。\\\\n\\\\n【詞義與名物】\\\\n「四輕」：地輕馬、馬輕車、車輕人、人輕戰。「二重一信」：進有重賞、退有重刑、行之以信。\\\\n\\\\n【兵家戰略】\\\\n吳起強調軍事組織的物質基礎與心理激勵。從地形、飼料、車軸保養、兵器防具，到最終士兵的作戰意願，環環相扣；再輔以賞罰分明與嚴守誠信，軍隊才能發揮最大戰力。"}},{"id":"wu-zi_ch-3_p-2","chapterId":"wu-zi_ch-3","order":2,"canonicalText":"武侯問曰：「兵何以為勝？」起對曰：「以治為勝。」又問曰：「不在眾寡？」對曰：「若法令不明，賞罰不信，金之不止，鼓之不進，雖有百萬，何益於用。所謂治者，居則有禮，動則有威，進不可當，退不可追，前卻有節，左右應麾，雖絕成陳，雖散成行。與之安，與之危，其眾可合而不可離，可用而不可疲，投之所往，天下莫當，名曰父子之兵。」","sentenceIds":["wu-zi_ch-3_p-2_s-1","wu-zi_ch-3_p-2_s-2","wu-zi_ch-3_p-2_s-3","wu-zi_ch-3_p-2_s-4","wu-zi_ch-3_p-2_s-5","wu-zi_ch-3_p-2_s-6","wu-zi_ch-3_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「軍隊依靠什麼來取得勝利？」吳起回答說：「依靠治理嚴整來取得勝利。」武侯又問：「不在於兵多兵少嗎？」回答說：「如果法令不明確，賞罰不講誠信，鳴金軍隊不停，擊鼓軍隊不進，即使有百萬大軍，對作戰又有什麼好處？所謂治理嚴整，是指平時駐紮則有禮節規範，行動則有軍威震懾，進攻時銳不可擋，撤退時無法追擊，前後移動有節奏，左右轉向順應旗揮，即使隊伍被截斷也能就地成陣，即使隊伍被分散也能迅速排成行列。與士兵同甘共苦、共患難，士眾就能團結凝聚而不可離散，持續作戰而不顯疲憊，投向何處都無人能擋，這就叫做『父子之兵』。」","analysis":"【主題與背景】\\\\n本段深刻論述軍紀組織力（治）高於單純兵力數量（眾）的軍事哲理，並提出「父子之兵」的至高軍隊境界。\\\\n\\\\n【詞義與名物】\\\\n「以治為勝」：軍隊勝負取決於組織嚴密與訓練有素而非數量。「父子之兵」：將帥與士兵關係親如父子、生死相依的部隊。\\\\n\\\\n【兵家戰略】\\\\n吳起指出軍事治理的極致是部隊具備高度的彈性與韌性（絕成陳、散成行），且將帥與士卒建立深厚的感情信任，使軍隊具備強大的凝聚力與戰鬥意志。"}},{"id":"wu-zi_ch-3_p-3","chapterId":"wu-zi_ch-3","order":3,"canonicalText":"吳子曰：「凡行軍之道，無犯進止之節，無失飲食之適，無絕人馬之力。此三者，所以任其上令。任其上令，則治之所由生也。若進止不度，飲食不適，馬疲人倦而不解舍，所以不任其上令。上令既廢，以居則亂，以戰則敗。」","sentenceIds":["wu-zi_ch-3_p-3_s-1","wu-zi_ch-3_p-3_s-2","wu-zi_ch-3_p-3_s-3","wu-zi_ch-3_p-3_s-4","wu-zi_ch-3_p-3_s-5","wu-zi_ch-3_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是行軍的法則，不要違反前進停止的節奏，不要失卻飲食調養的適度，不要耗盡人馬的體力。這三條，是用來貫徹上級命令的基礎。能夠貫徹上級命令，軍隊的嚴整治理就由此產生了。如果前進後退沒有限度，飲食調養不適當，馬匹疲憊人員倦怠卻不設營休息，這就會導致無法貫徹上級命令。上級命令一旦廢弛，駐紮就會混亂，作戰就會失敗。」","analysis":"【主題與背景】\\\\n本段強調行軍過程中的體力管理與作息節奏，指出合理的行軍管理是軍令暢通的物質保障。\\\\n\\\\n【詞義與名物】\\\\n「進止之節、飲食之適、無絕人馬之力」：行軍管理的「三不違」原則。「解舍」：放下裝備休息設營。\\\\n\\\\n【兵家戰略】\\\\n吳起深刻認識到士兵的生理與心理極限。將帥如果一味濫用軍令、無視士卒體力疲勞，軍令就會失去執行力，進而引發內部混亂與戰場潰敗。"}},{"id":"wu-zi_ch-3_p-4","chapterId":"wu-zi_ch-3","order":4,"canonicalText":"吳子曰：「凡兵戰之場，立屍之地。必死則生，幸生則死。其善將者，如坐漏船之中，伏燒屋之下，使智者不及謀，勇者不及怒，受敵可也。故曰：用兵之害，猶豫最大；三軍之災，生於狐疑。」","sentenceIds":["wu-zi_ch-3_p-4_s-1","wu-zi_ch-3_p-4_s-2","wu-zi_ch-3_p-4_s-3","wu-zi_ch-3_p-4_s-4","wu-zi_ch-3_p-4_s-5","wu-zi_ch-3_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「吳子曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「立屍之地」的情境，應當採取相應的具體對策，對於「必死則生」的情境，應當採取相應的具體對策，對於「幸生則死」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「吳子」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「吳子」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「生於」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「吳子」與「生於」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-3_p-5","chapterId":"wu-zi_ch-3","order":5,"canonicalText":"吳子曰：「夫人當死其所不能，敗其所不便。故用兵之法，教戒為先。一人學戰，教成十人。十人學戰，教成百人。百人學戰，教成千人。千人學戰，教成萬人。萬人學戰，教成三軍。以近待遠，以佚待勞，以飽待飢。圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。每變皆習，乃授其兵。是謂將事。」","sentenceIds":["wu-zi_ch-3_p-5_s-1","wu-zi_ch-3_p-5_s-2","wu-zi_ch-3_p-5_s-3","wu-zi_ch-3_p-5_s-4","wu-zi_ch-3_p-5_s-5","wu-zi_ch-3_p-5_s-6","wu-zi_ch-3_p-5_s-7","wu-zi_ch-3_p-5_s-8","wu-zi_ch-3_p-5_s-9","wu-zi_ch-3_p-5_s-10","wu-zi_ch-3_p-5_s-11","wu-zi_ch-3_p-5_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「吳子曰」的情境，應當採取相應的具體對策，治理國家應以安撫民眾為根本，對於「敗其所不」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「教戒為先」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「吳子」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「吳子」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「是謂」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「吳子」與「是謂」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-3_p-6","chapterId":"wu-zi_ch-3","order":6,"canonicalText":"吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。鄉里相比，什伍相保。一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。聞鼓聲合，然後舉旗。」","sentenceIds":["wu-zi_ch-3_p-6_s-1","wu-zi_ch-3_p-6_s-2","wu-zi_ch-3_p-6_s-3","wu-zi_ch-3_p-6_s-4","wu-zi_ch-3_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「吳子曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「短者持矛」的情境，應當採取相應的具體對策，對於「長者持弓」的情境，應當採取相應的具體對策，對於「強者持旌」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「吳子」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「吳子」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「然後」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「吳子」與「然後」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-3_p-7","chapterId":"wu-zi_ch-3","order":7,"canonicalText":"武侯問曰：「三軍進止。豈有道乎？」起對曰：「無當天竈，無當龍頭。天竈者，大谷之口。龍頭者，大山之端。必左青龍，右白虎，前朱雀，後玄武，招搖在上，從事於下。將戰之時，審候風所從來。風順致呼而從之，風逆堅陳以待之。」","sentenceIds":["wu-zi_ch-3_p-7_s-1","wu-zi_ch-3_p-7_s-2","wu-zi_ch-3_p-7_s-3","wu-zi_ch-3_p-7_s-4","wu-zi_ch-3_p-7_s-5","wu-zi_ch-3_p-7_s-6","wu-zi_ch-3_p-7_s-7","wu-zi_ch-3_p-7_s-8","wu-zi_ch-3_p-7_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「三軍的前進與停止，難道有法則規律嗎？」吳起回答說：「不要正對著『天竈』扎營，不要正對著『龍頭』扎營。所謂天竈，是指大山谷的谷口；所謂龍頭，是指大山的端頭頂峯。布陣必須左邊有青龍（水流），右邊有白虎（長道），前有朱雀（開闊地），後有玄武（高山地形），招搖星旗在上指引，部隊在下跟從行動。準備作戰時，仔細審察風向從何處吹來。風向順風就大聲呼喊順風追擊，風向逆風就堅固陣勢嚴陣以待。」","analysis":"【主題與背景】\\\\n本段論述地理選擇（安營紮寨）與戰場風向氣候利用的軍事地形學法則。\\\\n\\\\n【詞義與名物】\\\\n「天竈、龍頭」：危險不利安營的地形（谷口風大易受伏、山頂無水易被圍）。「左青龍右白虎前朱雀後玄武」：古代軍隊陣地四方地理防衛定位。\\\\n\\\\n【兵家戰略】\\\\n吳起利用傳統四象方位表達戰術地形選擇，要求部隊避免陷入谷口或山頂等絕地，並善於根據風向順逆調整進攻與防禦策略。"}},{"id":"wu-zi_ch-3_p-8","chapterId":"wu-zi_ch-3","order":8,"canonicalText":"武侯問曰：「凡畜卒騎，豈有方乎？」起對曰：「夫馬必安其處所，適其水草，節其飢飽。冬則溫燒，夏則涼廡。刻剔毛鬣，謹落四下。戢其耳目，無令驚駭。習其馳逐，閑其進止。人馬相親，然後可使。車騎之具，鞍、勒、銜、轡，必令完堅。凡馬不傷於末，必傷於始；不傷於飢，必傷於飽。日暮道遠，必數上下。寧勞於人，慎無勞馬。常令有餘，備敵覆我。能明此者，橫行天下。」","sentenceIds":["wu-zi_ch-3_p-8_s-1","wu-zi_ch-3_p-8_s-2","wu-zi_ch-3_p-8_s-3","wu-zi_ch-3_p-8_s-4","wu-zi_ch-3_p-8_s-5","wu-zi_ch-3_p-8_s-6","wu-zi_ch-3_p-8_s-7","wu-zi_ch-3_p-8_s-8","wu-zi_ch-3_p-8_s-9","wu-zi_ch-3_p-8_s-10","wu-zi_ch-3_p-8_s-11","wu-zi_ch-3_p-8_s-12","wu-zi_ch-3_p-8_s-13","wu-zi_ch-3_p-8_s-14","wu-zi_ch-3_p-8_s-15"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「養育訓練步兵與騎兵，難道有具體方法嗎？」吳起回答說：「馬匹必須使其居住處所安定，水草適宜，飲食飢飽有節制。冬天則設法保暖，夏天則保持涼爽。定期修剪毛鬣，謹慎釘好四蹄蹄鐵。使其耳目收斂不受驚嚇，練習其奔跑追逐，熟練其前進停止。人與馬親近信任，然後才可以使喚作戰。戰車與騎兵的裝備，鞍、勒、銜、轡，必須保持完好堅固。凡馬匹不受傷於後天，必受傷於開頭；不受傷於飢餓，必受傷於過飽。日落路遠之時，必須多次下馬步行。寧可讓人勞累，謹慎切勿使馬勞累。常使馬匹保持餘力，以防備敵人突襲覆滅我們。能明白這些道理的人，就能橫行天下。」","analysis":"【主題與背景】\\\\n本段詳細論述騎兵與馬匹養護管理、裝備保養的軍事後勤學細節。\\\\n\\\\n【詞義與名物】\\\\n「畜卒騎」：步兵與騎兵的養育管理。「寧勞於人，無勞於馬」：戰略後勤中保護騎兵核心戰鬥資源（戰馬）的至理名言。\\\\n\\\\n【兵家戰略】\\\\n吳起展現了極其細緻的後勤管理思維。戰馬是古代軍隊機動力的核心，通過節制飲食、定期保養裝備與避免過度勞累，保持馬匹戰鬥餘力，方能確保突發狀況下部隊的生存與勝算。"}},{"id":"wu-zi_ch-4_p-1","chapterId":"wu-zi_ch-4","order":1,"canonicalText":"吳子曰：「夫總文武者，軍之將也。兼剛柔者，兵之事也。凡人論將，常觀於勇。勇之於將，乃數分之一爾。夫勇者必輕合，輕合而不知利，未可也。故將之所慎者五：一曰理，二曰備，三曰果，四曰戒，五曰約。理者，治眾如治寡。備者，出門如見敵。果者，臨敵不懷生。戒者，雖克如始戰。約者，法令省而不煩。受命而不辭，敵破而後言返，將之禮也。故師出之日，有死之榮，無生之辱。」","sentenceIds":["wu-zi_ch-4_p-1_s-1","wu-zi_ch-4_p-1_s-2","wu-zi_ch-4_p-1_s-3","wu-zi_ch-4_p-1_s-4","wu-zi_ch-4_p-1_s-5","wu-zi_ch-4_p-1_s-6","wu-zi_ch-4_p-1_s-7","wu-zi_ch-4_p-1_s-8","wu-zi_ch-4_p-1_s-9","wu-zi_ch-4_p-1_s-10","wu-zi_ch-4_p-1_s-11","wu-zi_ch-4_p-1_s-12","wu-zi_ch-4_p-1_s-13","wu-zi_ch-4_p-1_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「吳子曰」的情境，應當採取相應的具體對策，對於「夫總文武」的情境，應當採取相應的具體對策，對於「軍之將也」的情境，應當採取相應的具體對策，對於「兼剛柔者」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「吳子」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「吳子」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「無生」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「吳子」與「無生」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-4_p-2","chapterId":"wu-zi_ch-4","order":2,"canonicalText":"吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。三軍之眾，百萬之師，張設輕重，在於一人，是謂氣機。路狹道險，名山大塞，十夫所守，千夫不過，是謂地機。善行間諜，輕兵往來，分散其眾，使其君臣相怨，上下相咎，是謂事機。車堅管轄，舟利櫓楫，士習戰陳，馬閑馳逐，是謂力機。知此四者，乃可為將。然其威、德、仁、勇，必足以率下安眾，怖敵決疑。施令而下不犯，所在寇不敢敵。得之國強，去之國亡。是謂良將。」","sentenceIds":["wu-zi_ch-4_p-2_s-1","wu-zi_ch-4_p-2_s-2","wu-zi_ch-4_p-2_s-3","wu-zi_ch-4_p-2_s-4","wu-zi_ch-4_p-2_s-5","wu-zi_ch-4_p-2_s-6","wu-zi_ch-4_p-2_s-7","wu-zi_ch-4_p-2_s-8","wu-zi_ch-4_p-2_s-9","wu-zi_ch-4_p-2_s-10","wu-zi_ch-4_p-2_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是軍事作戰有四種關鍵樞機：一是『氣機』，二是『地機』，三是『事機』，四是『力機』。三軍大眾、百萬之師，張設輕重戰術部署，全掌握在將領一人心中，這叫做氣機；道路狹窄通道險要，名山大川重要關隘，十個人防守一千個人也無法通過，這叫做地機；善於運用間諜，派輕捷部隊往來騷擾，分散敵人的兵力，使其君臣相互怨恨、上下相互責怪，這叫做事機；戰車堅固轄鍵完好，舟船利於劃槳，士卒熟練陣法，馬匹習慣馳騁，這叫做力機。懂得這四種樞機，才可以擔任將領。然而其威嚴、美德、仁愛、勇敢，必須足以統率下屬、安定士眾、震懾敵人、化解猜疑。發布命令而下屬不敢違犯，部隊駐紮之處敵人不敢抗衡。獲得這樣的將領國家就強盛，失去這樣的將領國家就滅亡。這就叫做良將。」","analysis":"【主題與背景】\\\\n本段提出軍事作戰的四大樞機（氣機、地機、事機、力機），並闡述良將對國家安危的決定性作用。\\\\n\\\\n【詞義與名物】\\\\n「四機」：氣機（精神士氣統率）、地機（地形關隘利用）、事機（情報間諜與離間術）、力機（裝備訓練戰力）。\\\\n\\\\n【兵家戰略】\\\\n吳起將將領能力分為心智士氣、地形利用、情報謀略與物質裝備四個層面。良將能有機整合這四大樞機，產生「得之國強，去之國亡」的戰略效果。"}},{"id":"wu-zi_ch-4_p-3","chapterId":"wu-zi_ch-4","order":3,"canonicalText":"吳子曰：「夫鼙鼓金鐸，所以威耳。旌旗麾幟，所以威目。禁令刑罰，所以威心。耳威於聲，不可不清。目威於色，不可不明。心威於刑，不可不嚴。三者不立，雖有其國，必敗於敵。故曰：將之所麾，莫不從移；將之所指，莫不前死。」","sentenceIds":["wu-zi_ch-4_p-3_s-1","wu-zi_ch-4_p-3_s-2","wu-zi_ch-4_p-3_s-3","wu-zi_ch-4_p-3_s-4","wu-zi_ch-4_p-3_s-5","wu-zi_ch-4_p-3_s-6","wu-zi_ch-4_p-3_s-7","wu-zi_ch-4_p-3_s-8","wu-zi_ch-4_p-3_s-9","wu-zi_ch-4_p-3_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「吳子曰」的情境，應當採取相應的具體對策，對於「夫鼙鼓金」的情境，應當採取相應的具體對策，對於「所以威耳」的情境，應當採取相應的具體對策，對於「旌旗麾幟」的情境，應當採取相應的具體對策，對於「所以威目」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「吳子」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「吳子」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「莫不」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「吳子」與「莫不」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-4_p-4","chapterId":"wu-zi_ch-4","order":4,"canonicalText":"吳子曰：「凡戰之要，必先佔其將而察其才。因形用權，則不勞而功舉。其將愚而信人，可詐而誘；貪而忽名，可貨而賂；輕變無謀，可勞而困。上富而驕，下貧而怨，可離而間。進退多疑，其眾無依，可震而走。士輕其將而有歸志，塞易開險，可邀而取。進道易，退道難，可來而前。進道險，退道易，可薄而擊。居軍下濕，水無所通，霖雨數至，可灌而沈。居軍荒澤，草楚幽穢，風飆數至，可焚而滅。停久不移，將士懈怠，其軍不備，可潛而襲。」","sentenceIds":["wu-zi_ch-4_p-4_s-1","wu-zi_ch-4_p-4_s-2","wu-zi_ch-4_p-4_s-3","wu-zi_ch-4_p-4_s-4","wu-zi_ch-4_p-4_s-5","wu-zi_ch-4_p-4_s-6","wu-zi_ch-4_p-4_s-7","wu-zi_ch-4_p-4_s-8","wu-zi_ch-4_p-4_s-9","wu-zi_ch-4_p-4_s-10","wu-zi_ch-4_p-4_s-11","wu-zi_ch-4_p-4_s-12","wu-zi_ch-4_p-4_s-13","wu-zi_ch-4_p-4_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是作戰的要領，必定要先推察敵方將領的性格並審察其才能。順應敵情採取權變戰術，就能不費大功告成。敵方將領如果愚蠢而輕信他人，可以用詐謀進行誘騙；如果貪婪而忽視名聲，可以用財貨進行賄賂；如果輕率易變缺乏謀略，可以用頻繁騷擾使其疲憊困頓；如果上層富有而驕縱、下層貧困而怨恨，可以用離間計進行分化；如果進退多疑、部眾無所適從，可以用震懾戰術使其逃跑；如果士兵輕視其將領且有回家心思，可以堵塞平坦道路、留出險要通道，在要衝伏擊討伐；如果敵人前進道路平坦、後退道路困難，可以引誘其深入然後進攻；如果敵人前進道路險要、後退道路平坦，可以逼近並打擊它；如果敵軍駐紮低窪潮濕之地、水流無法疏通，連續連降大雨，可以用大水淹沒沉沒它；如果敵軍駐紮荒野沼澤、草木幽深雜亂，狂風屢次吹來，可以用火攻將其焚毀滅絕；如果敵軍停駐許久不移動，將士懈怠防備鬆弛，可以用潛伏進行襲擊。」","analysis":"【主題與背景】\\\\n本段詳盡論述針對敵將性格缺陷（愚、貪、輕、驕、疑）與敵軍駐紮環境（水、火、地形）採取的十二種權變打擊戰術。\\\\n\\\\n【詞義與名物】\\\\n「佔將察才」：評估敵方指揮官的心理與性格弱點。「因形用權」：根據敵人具體形態變化靈活運用權變戰術。\\\\n\\\\n【兵家戰略】\\\\n吳起主張「針對性格與環境缺陷破敵」。敵將性格上的貪婪、多疑、輕率，以及敵軍駐地的水火地形隱患，都是兵家可以無損獲勝的打擊突破口。"}},{"id":"wu-zi_ch-4_p-5","chapterId":"wu-zi_ch-4","order":5,"canonicalText":"武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？」起對曰：「令賤而勇者，將輕銳以嘗之。務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。」","sentenceIds":["wu-zi_ch-4_p-5_s-1","wu-zi_ch-4_p-5_s-2","wu-zi_ch-4_p-5_s-3","wu-zi_ch-4_p-5_s-4","wu-zi_ch-4_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，對於「兩軍相望」的情境，應當採取相應的具體對策，對於「不知其將」的情境，應當採取相應的具體對策，對於「我欲相之」的情境，應當採取相應的具體對策，對於「其術如何」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「雖眾」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「雖眾」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-1","chapterId":"wu-zi_ch-5","order":1,"canonicalText":"武侯問曰：「車堅馬良，將勇兵強，卒遇敵人，亂而失行，則如之何？」起對曰：「凡戰之法，晝以旌旗旛麾為節，夜以金鼓笳笛為節。麾左而左，麾右而右。鼓之則進，金之則止。二吹而行，再吹而聚，不從令者誅。三軍服威，士卒用命，則戰無彊敵，攻無堅陳矣。」","sentenceIds":["wu-zi_ch-5_p-1_s-1","wu-zi_ch-5_p-1_s-2","wu-zi_ch-5_p-1_s-3","wu-zi_ch-5_p-1_s-4","wu-zi_ch-5_p-1_s-5","wu-zi_ch-5_p-1_s-6","wu-zi_ch-5_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，對於「車堅馬良」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「亂而失行」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「攻無」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「攻無」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-2","chapterId":"wu-zi_ch-5","order":2,"canonicalText":"武侯問曰：「若敵眾我寡，為之柰何？」起對曰：「避之於易，邀之於阨。故曰：以一擊十，莫善於阨；以十擊百，莫善於險；以千擊萬，莫善於阻。今有少年卒起，擊金鳴鼓於阨路，雖有大眾，莫不驚動。故曰：用眾者務易，用少者務隘。」","sentenceIds":["wu-zi_ch-5_p-2_s-1","wu-zi_ch-5_p-2_s-2","wu-zi_ch-5_p-2_s-3","wu-zi_ch-5_p-2_s-4","wu-zi_ch-5_p-2_s-5","wu-zi_ch-5_p-2_s-6","wu-zi_ch-5_p-2_s-7","wu-zi_ch-5_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「為之柰何」的情境，應當採取相應的具體對策，對於「起對曰」的情境，應當採取相應的具體對策，對於「避之於易」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「用少」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「用少」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-3","chapterId":"wu-zi_ch-5","order":3,"canonicalText":"武侯問曰：「有師甚眾，既武且勇；背大險阻，右山左水；深溝高壘，守以彊弩；退如山移，進如風雨，糧食又多。難與長守。」對曰：「大哉問乎！非此車騎之力，聖人之謀也。能備千乘萬騎，兼之徒步，分為五軍，各軍一衢。夫五軍五衢，敵人必惑，莫之所加。敵人若堅守以固其兵，急行間諜以觀其慮。彼聽吾說，解之而去。不聽吾說，斬使焚書，分為五戰。戰勝勿追，不勝疾歸。如是佯北，安行疾鬭，一結其前，一絕其後。兩軍𠾑枚，或左或右，而襲其處。五軍交至，必有其力。此擊彊之道也。」","sentenceIds":["wu-zi_ch-5_p-3_s-1","wu-zi_ch-5_p-3_s-2","wu-zi_ch-5_p-3_s-3","wu-zi_ch-5_p-3_s-4","wu-zi_ch-5_p-3_s-5","wu-zi_ch-5_p-3_s-6","wu-zi_ch-5_p-3_s-7","wu-zi_ch-5_p-3_s-8","wu-zi_ch-5_p-3_s-9","wu-zi_ch-5_p-3_s-10","wu-zi_ch-5_p-3_s-11","wu-zi_ch-5_p-3_s-12","wu-zi_ch-5_p-3_s-13","wu-zi_ch-5_p-3_s-14","wu-zi_ch-5_p-3_s-15","wu-zi_ch-5_p-3_s-16","wu-zi_ch-5_p-3_s-17","wu-zi_ch-5_p-3_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「如果有敵軍人數極多，既武藝高強又勇敢；背靠大險阻地形，右邊是山陵左邊是水流；築有深溝高壘，用強弩堅守；後退時如山嶽移動，前進時如風雨交加，糧食儲備又多，很難與其長期對峙僵持。」吳起回答說：「這是多麼高明的大問題啊！這不是普通戰車騎兵所能解決的，必須靠聖人般的謀略纔行。應當裝備千乘戰車萬匹騎兵，加上步兵，分為五支軍隊，每軍佔據一條要道。五軍五道，敵人必定困惑，不知道該防備哪裡。敵人如果堅守以固守其部隊，迅速派遣間諜去觀察其企圖想法。敵若聽信我方說辭間諜勸誘，解圍離去；若不聽我方說辭，殺害使者焚燒書信，就分為五路發起進攻。戰勝了不要盲目追擊，不勝就迅速撤回。像這樣佯裝敗退，從容撤退快速戰鬥，一路牽制敵前，一路切斷敵後。兩軍口銜枚默默行動，或左或右，襲擊敵軍營寨。五軍交替到達，必定發揮巨大威力。這就是打擊強大敵軍的途徑。」","analysis":"【主題與背景】\\\\n本段回答如何破解佔盡地形、兵力、糧餉優勢且防守堅固之敵的戰略巨題。\\\\n\\\\n【詞義與名物】\\\\n「五軍五衢」：將部隊分為五路多線並進，分散並惑亂敵軍集中兵力。「銜枚」：口含木枚防止部隊行動發出聲音，進行隱蔽夜襲。\\\\n\\\\n【兵家戰略】\\\\n吳起針對強敵提出了「多線心理威嚇、間諜分化、多路佯攻與機動襲擊」的複合戰略。不硬攻堅壘，而是通過多路機動與襲擊切斷敵人糧道後方，動搖其堅守意志。"}},{"id":"wu-zi_ch-5_p-4","chapterId":"wu-zi_ch-5","order":4,"canonicalText":"武侯問曰：「敵近而薄我，欲去無路，我眾甚懼，為之柰何？」對曰：「為此之術，若我眾彼寡，各分而乘之。彼眾我寡，以方從之。從之無息，雖眾可服。」","sentenceIds":["wu-zi_ch-5_p-4_s-1","wu-zi_ch-5_p-4_s-2","wu-zi_ch-5_p-4_s-3","wu-zi_ch-5_p-4_s-4","wu-zi_ch-5_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「欲去無路」的情境，應當採取相應的具體對策，對於「我眾甚懼」的情境，應當採取相應的具體對策，對於「為之柰何」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「雖眾」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「雖眾」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-5","chapterId":"wu-zi_ch-5","order":5,"canonicalText":"武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。若高山深谷，卒然相遇，必先鼓譟而乘之。進弓與弩，且射且虜。審察其政，亂則擊之勿疑。」","sentenceIds":["wu-zi_ch-5_p-5_s-1","wu-zi_ch-5_p-5_s-2","wu-zi_ch-5_p-5_s-3","wu-zi_ch-5_p-5_s-4","wu-zi_ch-5_p-5_s-5","wu-zi_ch-5_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「傍多險阻」的情境，應當採取相應的具體對策，對於「彼眾我寡」的情境，應當採取相應的具體對策，對於「為之奈何」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「亂則」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「亂則」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-6","chapterId":"wu-zi_ch-5","order":6,"canonicalText":"武侯問曰：「左右高山，地甚狹迫，卒遇敵人，擊之不敢，去之不得，為之奈何？」起對曰：「此謂谷戰，雖眾不用。募吾材士與敵相當，輕足利兵以為前行，分車列騎隱於四旁，相去數裏，無見其兵，敵必堅陳，進退不敢。於是出旌列旆，行出山外營之，敵人必懼。車騎挑之，勿令得休。此谷戰之法也。」","sentenceIds":["wu-zi_ch-5_p-6_s-1","wu-zi_ch-5_p-6_s-2","wu-zi_ch-5_p-6_s-3","wu-zi_ch-5_p-6_s-4","wu-zi_ch-5_p-6_s-5","wu-zi_ch-5_p-6_s-6","wu-zi_ch-5_p-6_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，對於「左右高山」的情境，應當採取相應的具體對策，對於「地甚狹迫」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「擊之不敢」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「此谷」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「此谷」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-7","chapterId":"wu-zi_ch-5","order":7,"canonicalText":"武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？」起對曰：「此謂水戰，無用車騎，且留其傍。登高四望，必得水情。知其廣狹，盡其淺深，乃可為奇以勝之。敵若絕水，半渡而薄之。」","sentenceIds":["wu-zi_ch-5_p-7_s-1","wu-zi_ch-5_p-7_s-2","wu-zi_ch-5_p-7_s-3","wu-zi_ch-5_p-7_s-4","wu-zi_ch-5_p-7_s-5","wu-zi_ch-5_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「傾輪沒轅」的情境，應當採取相應的具體對策，對於「水薄車騎」的情境，應當採取相應的具體對策，對於「舟楫不設」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「半渡」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「半渡」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-8","chapterId":"wu-zi_ch-5","order":8,"canonicalText":"武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？」起對曰：「凡用車者，陰濕則停，陽燥則起；貴高賤下，馳其強車；若進若止，必從其道。敵人若起，必逐其跡。」","sentenceIds":["wu-zi_ch-5_p-8_s-1","wu-zi_ch-5_p-8_s-2","wu-zi_ch-5_p-8_s-3","wu-zi_ch-5_p-8_s-4","wu-zi_ch-5_p-8_s-5","wu-zi_ch-5_p-8_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「天氣長期連降大雨，戰馬陷泥戰車停滯，四面遭受敵人包圍，三軍驚慌害怕，該怎麼辦呢？」吳起回答說：「凡是使用戰車的原則，陰雨潮濕時就停止行動，晴朗乾燥時就開起行動；尊崇高處避開低窪，在堅硬地面馳騁精良戰車；無論前進還是停止，必定要順應道路。敵人如果行動發起攻擊，必定要順著敵人的足跡進行追擊打擊。」","analysis":"【主題與背景】\\\\n本段論述連雨泥濘、戰車陷泥且四面受敵時的地理選擇與跟蹤反擊戰術。\\\\n\\\\n【詞義與名物】\\\\n「貴高賤下」：戰車作戰選擇高處堅硬地帶、避開低窪泥濘之地的原則。「逐其跡」：順著敵軍踩出的安全路徑反擊。\\\\n\\\\n【兵家戰略】\\\\n吳起強調氣候與路況對戰車作戰的制約。在泥濘困境中應迅速撤往高處堅地；敵軍若能推進，說明敵軍路徑安全，順著敵軍足跡反擊即可化解被圍危機。"}},{"id":"wu-zi_ch-5_p-9","chapterId":"wu-zi_ch-5","order":9,"canonicalText":"武侯問曰：「暴寇卒來，掠吾田野，取吾牛羊，則如之何？」","sentenceIds":["wu-zi_ch-5_p-9_s-1","wu-zi_ch-5_p-9_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，對於「暴寇卒來」的情境，應當採取相應的具體對策，對於「掠吾田野」的情境，應當採取相應的具體對策，對於「取吾牛羊」的情境，應當採取相應的具體對策，對於「則如之何」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「則如」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「則如」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-10","chapterId":"wu-zi_ch-5","order":10,"canonicalText":"起對曰：「暴寇之來，必慮其強，善守勿應。彼將暮去，其裝必重，其心必恐，還退務速，必有不屬。追而擊之，其兵可覆。」","sentenceIds":["wu-zi_ch-5_p-10_s-1","wu-zi_ch-5_p-10_s-2","wu-zi_ch-5_p-10_s-3","wu-zi_ch-5_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「起對曰」的情境，應當採取相應的具體對策，對於「暴寇之來」的情境，應當採取相應的具體對策，對於「必慮其強」的情境，應當採取相應的具體對策，對於「善守勿應」的情境，應當採取相應的具體對策，對於「彼將暮去」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「起對」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「起對」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「其兵」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「起對」與「其兵」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-5_p-11","chapterId":"wu-zi_ch-5","order":11,"canonicalText":"吳子曰：「凡攻敵圍城之道，城邑既破，各入其宮。御其祿秩，收其器物。軍之所至，無刊其木、發其屋、取其粟、殺其六畜、燔其積聚，示民無殘心。其有請降，許而安之。」","sentenceIds":["wu-zi_ch-5_p-11_s-1","wu-zi_ch-5_p-11_s-2","wu-zi_ch-5_p-11_s-3","wu-zi_ch-5_p-11_s-4","wu-zi_ch-5_p-11_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是攻打敵人圍守城池的法則，城池攻破之後，各部隊進入相應宮室官署。掌控其官爵奉祿檔案，接收其武器器物。軍隊所到之處，不得砍伐樹木、拆毀房屋、搶奪糧食、屠殺六畜、焚燒囤積物資，向敵國百姓展示沒有殘害之心。如果有請求投降的，應當允許並安撫他們。」","analysis":"【主題與背景】\\\\n本段論述破城之後的城市接管政策與嚴明軍紀，強調「示民無殘心」的政治安撫戰略。\\\\n\\\\n【詞義與名物】\\\\n「御祿秩」：接管掌控敵國的官制與檔案紀錄。「無殘心」：展示不殘害平民百姓的正義之師形象。\\\\n\\\\n【兵家戰略】\\\\n吳起將攻城戰延伸至政治接管層面。嚴禁破壞農木民房糧草，安撫降民，能最大限度降低敵國反抗情緒，快速穩定戰後秩序，實現真正的軍事與政治勝利。"}},{"id":"wu-zi_ch-6_p-1","chapterId":"wu-zi_ch-6","order":1,"canonicalText":"武侯問曰：「嚴刑明賞，足以勝乎？」起對曰：「嚴明之事，臣不能悉。雖然，非所恃也。夫發號布令而人樂聞，興師動眾而人樂戰，交兵接刃而人樂死。此三者，人主之所恃也。」","sentenceIds":["wu-zi_ch-6_p-1_s-1","wu-zi_ch-6_p-1_s-2","wu-zi_ch-6_p-1_s-3","wu-zi_ch-6_p-1_s-4","wu-zi_ch-6_p-1_s-5","wu-zi_ch-6_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯問曰」的情境，應當採取相應的具體對策，必須建立明確的賞罰與法度，對於「足以勝乎」的情境，應當採取相應的具體對策，對於「起對曰」的情境，應當採取相應的具體對策，對於「嚴明之事」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「人主」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「人主」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-6_p-2","chapterId":"wu-zi_ch-6","order":2,"canonicalText":"武侯曰：「致之奈何？」對曰：「君舉有功而進饗之，無功而勵之。」","sentenceIds":["wu-zi_ch-6_p-2_s-1","wu-zi_ch-6_p-2_s-2","wu-zi_ch-6_p-2_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯曰」的情境，應當採取相應的具體對策，對於「致之奈何」的情境，應當採取相應的具體對策，對於「對曰」的情境，應當採取相應的具體對策，領導者應具備深遠的眼光與美德，對於「無功而勵」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「無功」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「無功」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-6_p-3","chapterId":"wu-zi_ch-6","order":3,"canonicalText":"於是武侯設坐廟廷為三行饗士大夫。上功坐前行，餚席兼重器、上牢。次功坐中行，餚席器差減。無功坐後行，餚席無重器。饗畢而出，又頒賜有功者父母妻子於廟門外，亦以功為差。有死事之家，歲被使者勞賜其父母，著不忘於心。行之三年，秦人興師，臨於西河，魏士聞之，不待吏令，介冑而奮擊之者以萬數。","sentenceIds":["wu-zi_ch-6_p-3_s-1","wu-zi_ch-6_p-3_s-2","wu-zi_ch-6_p-3_s-3","wu-zi_ch-6_p-3_s-4","wu-zi_ch-6_p-3_s-5","wu-zi_ch-6_p-3_s-6","wu-zi_ch-6_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「於是武侯」的情境，應當採取相應的具體對策，對於「上功坐前」的情境，應當採取相應的具體對策，對於「餚席兼重」的情境，應當採取相應的具體對策，對於「上牢」的情境，應當採取相應的具體對策，對於「次功坐中」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「於是」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「於是」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「介冑」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「於是」與「介冑」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-6_p-4","chapterId":"wu-zi_ch-6","order":4,"canonicalText":"武侯召吳起而謂曰：「子前日之教行矣。」起對曰：「臣聞人有短長，氣有盛衰。君試發無功者五萬人，臣請率以當之。脫其不勝，取笑於諸侯，失權於天下矣。今使一死賊伏於曠野，千人追之，莫不梟視狼顧。何者？忌其暴起而害己。是以一人投命，足懼千夫。今臣以五萬之眾，而為一死賊，率以討之，固難敵矣。」","sentenceIds":["wu-zi_ch-6_p-4_s-1","wu-zi_ch-6_p-4_s-2","wu-zi_ch-6_p-4_s-3","wu-zi_ch-6_p-4_s-4","wu-zi_ch-6_p-4_s-5","wu-zi_ch-6_p-4_s-6","wu-zi_ch-6_p-4_s-7","wu-zi_ch-6_p-4_s-8","wu-zi_ch-6_p-4_s-9","wu-zi_ch-6_p-4_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：對於「武侯召吳」的情境，應當採取相應的具體對策，對於「子前日之」的情境，應當採取相應的具體對策，對於「起對曰」的情境，應當採取相應的具體對策，治理國家應以安撫民眾為根本，對於「氣有盛衰」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「武侯」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「武侯」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「固難」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「武侯」與「固難」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}},{"id":"wu-zi_ch-6_p-5","chapterId":"wu-zi_ch-6","order":5,"canonicalText":"於是武侯從之，兼車五百乘，騎三千匹，而破秦五十萬眾，此勵士之功也。","sentenceIds":["wu-zi_ch-6_p-5_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"於是魏武侯聽從了他的建議，派戰車五百乘、騎兵三千匹，配屬吳起率領五萬精兵，結果大敗秦軍五十萬大軍，這就是勵士激勵士卒產生的巨大功績。","analysis":"【主題與背景】\\\\n本段記錄了戰國歷史上以少勝多的經典戰役——陰晉之戰，吳起以五萬魏武卒大破五十萬秦軍。\\\\n\\\\n【詞義與名物】\\\\n「陰晉之戰」：西元前389年魏國吳起以五萬大軍擊敗秦軍五十萬的輝煌戰役。\\\\n\\\\n【兵家戰略】\\\\n本段是《吳子兵法》全書的總結。五萬經過嚴格訓練、深受榮譽感激勵且無後顧之憂的精銳部隊，在優質車騎配合下，擊敗了十倍於己的敵人，證明瞭政治教化與軍事勵士的至高威力。"}},{"id":"wu-zi_ch-6_p-6","chapterId":"wu-zi_ch-6","order":6,"canonicalText":"先戰一日，吳起令三軍曰：「諸吏士當從受馳。車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。」故戰之日，其令不煩而威震天下。","sentenceIds":["wu-zi_ch-6_p-6_s-1","wu-zi_ch-6_p-6_s-2","wu-zi_ch-6_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"此段大意是說：在軍事行動中必須掌握敵我態勢並靈活調度，對於「吳起令三」的情境，應當採取相應的具體對策，對於「諸吏士當」的情境，應當採取相應的具體對策，對於「車騎與徒」的情境，應當採取相應的具體對策，對於「若車不得」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「先戰」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「先戰」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「其令」：反映了資源分配或戰術部署上的實際考量。\\n\\n【兵家戰略】\\n這顯示了兵家在面對「先戰」與「其令」時，強調因地制宜與靈活應變的戰略眼光。這為後世提供了重要的實踐參考。"}}],"sentences":[{"id":"wu-zi_ch-1_p-1_s-1","passageId":"wu-zi_ch-1_p-1","order":1,"canonicalText":"吳起儒服以兵機見魏文侯。","chunks":[["吳起儒服以兵機見魏文侯。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-2","passageId":"wu-zi_ch-1_p-1","order":2,"canonicalText":"文侯曰：「寡人不好軍旅之事。","chunks":[["文侯曰：「寡人不好軍旅之事。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-3","passageId":"wu-zi_ch-1_p-1","order":3,"canonicalText":"」起曰：「臣以見佔隱，以往察來，主君何言與心違？","chunks":[["」起曰：「臣以見佔隱，以往察來，主君何言與心違？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-4","passageId":"wu-zi_ch-1_p-1","order":4,"canonicalText":"今君四時使斬離皮革，掩以朱漆，畫以丹青，爍以犀象。","chunks":[["今君四時使斬離皮革，掩以朱漆，畫以丹青，爍以犀象。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-5","passageId":"wu-zi_ch-1_p-1","order":5,"canonicalText":"冬日衣之則不溫，夏日衣之則不涼。","chunks":[["冬日衣之則不溫，夏日衣之則不涼。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-6","passageId":"wu-zi_ch-1_p-1","order":6,"canonicalText":"為長戟二丈四尺，短戟一丈二尺。","chunks":[["為長戟二丈四尺，短戟一丈二尺。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-7","passageId":"wu-zi_ch-1_p-1","order":7,"canonicalText":"革車奄戶，縵輪籠轂，觀之於目則不麗，乘之以田則不輕，不識主君安用此也？","chunks":[["革車奄戶，縵輪籠轂，觀之於目則不麗，乘之以田則不輕，不識主君安用此也？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-8","passageId":"wu-zi_ch-1_p-1","order":8,"canonicalText":"若以備進戰退守，而不求能用者，譬猶伏雞之搏狸，乳犬之犯虎，雖有鬥心，隨之死矣。","chunks":[["若以備進戰退守，而不求能用者，譬猶伏雞之搏狸，乳犬之犯虎，雖有鬥心，隨之死矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-9","passageId":"wu-zi_ch-1_p-1","order":9,"canonicalText":"昔承桑氏之君，修德廢武，以滅其國。","chunks":[["昔承桑氏之君，修德廢武，以滅其國。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-10","passageId":"wu-zi_ch-1_p-1","order":10,"canonicalText":"有扈氏之君，恃眾好勇，以喪其社稷。","chunks":[["有扈氏之君，恃眾好勇，以喪其社稷。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-11","passageId":"wu-zi_ch-1_p-1","order":11,"canonicalText":"明主鑒茲，必內修文德，外治武備。","chunks":[["明主鑒茲，必內修文德，外治武備。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-12","passageId":"wu-zi_ch-1_p-1","order":12,"canonicalText":"故當敵而不進，無逮於義矣；","chunks":[["故當敵而不進，無逮於義矣；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-13","passageId":"wu-zi_ch-1_p-1","order":13,"canonicalText":"僵屍而哀之，無逮於仁矣。","chunks":[["僵屍而哀之，無逮於仁矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-14","passageId":"wu-zi_ch-1_p-1","order":14,"canonicalText":"」於是文侯身自布席，夫人捧觴，醮吳起於廟，立為大將，守西河。","chunks":[["」於是文侯身自布席，夫人捧觴，醮吳起於廟，立為大將，守西河。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-15","passageId":"wu-zi_ch-1_p-1","order":15,"canonicalText":"與諸侯大戰七十六，全勝六十四，餘則鈞解。","chunks":[["與諸侯大戰七十六，全勝六十四，餘則鈞解。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-16","passageId":"wu-zi_ch-1_p-1","order":16,"canonicalText":"闢土四面，拓地千里，皆起之功也。","chunks":[["闢土四面，拓地千里，皆起之功也。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-1","passageId":"wu-zi_ch-1_p-2","order":1,"canonicalText":"吳子曰：「昔之圖國家者，必先教百姓而親萬民。","chunks":[["吳子曰：「昔之圖國家者，必先教百姓而親萬民。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-2","passageId":"wu-zi_ch-1_p-2","order":2,"canonicalText":"有四不和：不和於國，不可以出軍；","chunks":[["有四不和：不和於國，不可以出軍；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-3","passageId":"wu-zi_ch-1_p-2","order":3,"canonicalText":"不和於軍，不可以出陳；","chunks":[["不和於軍，不可以出陳；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-4","passageId":"wu-zi_ch-1_p-2","order":4,"canonicalText":"不和於陳，不可以進戰；","chunks":[["不和於陳，不可以進戰；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-5","passageId":"wu-zi_ch-1_p-2","order":5,"canonicalText":"不和於戰，不可以決勝。","chunks":[["不和於戰，不可以決勝。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-6","passageId":"wu-zi_ch-1_p-2","order":6,"canonicalText":"是以有道之主，將用其民，先和而造大事。","chunks":[["是以有道之主，將用其民，先和而造大事。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-7","passageId":"wu-zi_ch-1_p-2","order":7,"canonicalText":"不敢信其私謀，必告於祖廟，啟於元龜，參之天時，吉乃後舉。","chunks":[["不敢信其私謀，必告於祖廟，啟於元龜，參之天時，吉乃後舉。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-8","passageId":"wu-zi_ch-1_p-2","order":8,"canonicalText":"民知君之愛其命，惜其死，若此之至，而與之臨難，則士以盡死為榮，退生為辱矣。","chunks":[["民知君之愛其命，惜其死，若此之至，而與之臨難，則士以盡死為榮，退生為辱矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-9","passageId":"wu-zi_ch-1_p-2","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-1","passageId":"wu-zi_ch-1_p-3","order":1,"canonicalText":"吳子曰：「夫道者，所以反本復始。","chunks":[["吳子曰：「夫道者，所以反本復始。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-2","passageId":"wu-zi_ch-1_p-3","order":2,"canonicalText":"義者，所以行事立功。","chunks":[["義者，所以行事立功。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-3","passageId":"wu-zi_ch-1_p-3","order":3,"canonicalText":"謀者，所以違害就利。","chunks":[["謀者，所以違害就利。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-4","passageId":"wu-zi_ch-1_p-3","order":4,"canonicalText":"要者，所以保業守成。","chunks":[["要者，所以保業守成。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-5","passageId":"wu-zi_ch-1_p-3","order":5,"canonicalText":"若行不合道，舉不合義，而處大居貴，患必及之。","chunks":[["若行不合道，舉不合義，而處大居貴，患必及之。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-6","passageId":"wu-zi_ch-1_p-3","order":6,"canonicalText":"是以聖人綏之以道，理之以義，動之以禮，撫之以仁。","chunks":[["是以聖人綏之以道，理之以義，動之以禮，撫之以仁。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-7","passageId":"wu-zi_ch-1_p-3","order":7,"canonicalText":"此四德者，修之則興，廢之則衰。","chunks":[["此四德者，修之則興，廢之則衰。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-8","passageId":"wu-zi_ch-1_p-3","order":8,"canonicalText":"故成湯討桀而夏民喜悅，周武伐紂而殷人不非。","chunks":[["故成湯討桀而夏民喜悅，周武伐紂而殷人不非。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-9","passageId":"wu-zi_ch-1_p-3","order":9,"canonicalText":"舉順天人，故能然矣。","chunks":[["舉順天人，故能然矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-10","passageId":"wu-zi_ch-1_p-3","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-1","passageId":"wu-zi_ch-1_p-4","order":1,"canonicalText":"吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。","chunks":[["吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-2","passageId":"wu-zi_ch-1_p-4","order":2,"canonicalText":"夫人有恥，在大足以戰，在小足以守矣。","chunks":[["夫人有恥，在大足以戰，在小足以守矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-3","passageId":"wu-zi_ch-1_p-4","order":3,"canonicalText":"然戰勝易，守勝難。","chunks":[["然戰勝易，守勝難。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-4","passageId":"wu-zi_ch-1_p-4","order":4,"canonicalText":"故曰：天下戰國，五勝者禍，四勝者弊，三勝者霸，二勝者王，一勝者帝。","chunks":[["故曰：天下戰國，五勝者禍，四勝者弊，三勝者霸，二勝者王，一勝者帝。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-5","passageId":"wu-zi_ch-1_p-4","order":5,"canonicalText":"是以數勝得天下者稀，以亡者眾。","chunks":[["是以數勝得天下者稀，以亡者眾。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-6","passageId":"wu-zi_ch-1_p-4","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-1","passageId":"wu-zi_ch-1_p-5","order":1,"canonicalText":"吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。","chunks":[["吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-2","passageId":"wu-zi_ch-1_p-5","order":2,"canonicalText":"其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。","chunks":[["其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-3","passageId":"wu-zi_ch-1_p-5","order":3,"canonicalText":"禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。","chunks":[["禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-4","passageId":"wu-zi_ch-1_p-5","order":4,"canonicalText":"五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。","chunks":[["五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-5","passageId":"wu-zi_ch-1_p-5","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-1","passageId":"wu-zi_ch-1_p-6","order":1,"canonicalText":"武侯問曰：「願聞治兵、料人、固國之道。","chunks":[["武侯問曰：「願聞治兵、料人、固國之道。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-2","passageId":"wu-zi_ch-1_p-6","order":2,"canonicalText":"」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。","chunks":[["」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-3","passageId":"wu-zi_ch-1_p-6","order":3,"canonicalText":"昔齊桓募士五萬，以霸諸侯。","chunks":[["昔齊桓募士五萬，以霸諸侯。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-4","passageId":"wu-zi_ch-1_p-6","order":4,"canonicalText":"晉文召為前行四萬，以獲其志。","chunks":[["晉文召為前行四萬，以獲其志。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-5","passageId":"wu-zi_ch-1_p-6","order":5,"canonicalText":"秦繆置陷陳三萬，以服鄰敵。","chunks":[["秦繆置陷陳三萬，以服鄰敵。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-6","passageId":"wu-zi_ch-1_p-6","order":6,"canonicalText":"故強國之君，必料其民。","chunks":[["故強國之君，必料其民。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-7","passageId":"wu-zi_ch-1_p-6","order":7,"canonicalText":"民有膽勇氣力者，聚為一卒。","chunks":[["民有膽勇氣力者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-8","passageId":"wu-zi_ch-1_p-6","order":8,"canonicalText":"樂以進戰效力、以顯其忠勇者，聚為一卒。","chunks":[["樂以進戰效力、以顯其忠勇者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-9","passageId":"wu-zi_ch-1_p-6","order":9,"canonicalText":"能踰高超遠、輕足善走者，聚為一卒。","chunks":[["能踰高超遠、輕足善走者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-10","passageId":"wu-zi_ch-1_p-6","order":10,"canonicalText":"王臣失位而欲見功於上者，聚為一卒。","chunks":[["王臣失位而欲見功於上者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-11","passageId":"wu-zi_ch-1_p-6","order":11,"canonicalText":"棄城去守、欲除其醜者，聚為一卒。","chunks":[["棄城去守、欲除其醜者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-12","passageId":"wu-zi_ch-1_p-6","order":12,"canonicalText":"此五者，軍之練銳也。","chunks":[["此五者，軍之練銳也。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-13","passageId":"wu-zi_ch-1_p-6","order":13,"canonicalText":"有此三千人，內出可以決圍，外入可以屠城矣。","chunks":[["有此三千人，內出可以決圍，外入可以屠城矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-14","passageId":"wu-zi_ch-1_p-6","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-1","passageId":"wu-zi_ch-1_p-7","order":1,"canonicalText":"武侯問曰：「願聞陳必定、守必固、戰必勝之道。","chunks":[["武侯問曰：「願聞陳必定、守必固、戰必勝之道。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-2","passageId":"wu-zi_ch-1_p-7","order":2,"canonicalText":"」起對曰：「立見且可，豈直聞乎！","chunks":[["」起對曰：「立見且可，豈直聞乎！","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-3","passageId":"wu-zi_ch-1_p-7","order":3,"canonicalText":"君能使賢者居上，不肖者處下，則陳已定矣。","chunks":[["君能使賢者居上，不肖者處下，則陳已定矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-4","passageId":"wu-zi_ch-1_p-7","order":4,"canonicalText":"民安其田宅，親其有司，則守已固矣。","chunks":[["民安其田宅，親其有司，則守已固矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-5","passageId":"wu-zi_ch-1_p-7","order":5,"canonicalText":"百姓皆是吾君而非鄰國，則戰已勝矣。","chunks":[["百姓皆是吾君而非鄰國，則戰已勝矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-6","passageId":"wu-zi_ch-1_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-1","passageId":"wu-zi_ch-1_p-8","order":1,"canonicalText":"武侯嘗謀事，群臣莫能及，罷朝而有喜色。","chunks":[["武侯嘗謀事，群臣莫能及，罷朝而有喜色。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-2","passageId":"wu-zi_ch-1_p-8","order":2,"canonicalText":"起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。","chunks":[["起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-3","passageId":"wu-zi_ch-1_p-8","order":3,"canonicalText":"申公問曰：『君有憂色，何也？","chunks":[["申公問曰：『君有憂色，何也？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-4","passageId":"wu-zi_ch-1_p-8","order":4,"canonicalText":"』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。","chunks":[["』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-5","passageId":"wu-zi_ch-1_p-8","order":5,"canonicalText":"今寡人不才，而群臣莫及者，楚國其殆矣。","chunks":[["今寡人不才，而群臣莫及者，楚國其殆矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-6","passageId":"wu-zi_ch-1_p-8","order":6,"canonicalText":"』此楚莊王之所憂，而君說之，臣竊懼矣。","chunks":[["』此楚莊王之所憂，而君說之，臣竊懼矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-7","passageId":"wu-zi_ch-1_p-8","order":7,"canonicalText":"」於是武侯有慚色。","chunks":[["」於是武侯有慚色。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-1","passageId":"wu-zi_ch-2_p-1","order":1,"canonicalText":"武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。","chunks":[["武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-2","passageId":"wu-zi_ch-2_p-1","order":2,"canonicalText":"六國兵四守，勢甚不便，憂此奈何？","chunks":[["六國兵四守，勢甚不便，憂此奈何？","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-3","passageId":"wu-zi_ch-2_p-1","order":3,"canonicalText":"」起對曰：「夫安國家之道，先戒為寶。","chunks":[["」起對曰：「夫安國家之道，先戒為寶。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-4","passageId":"wu-zi_ch-2_p-1","order":4,"canonicalText":"今君已戒，禍其遠矣。","chunks":[["今君已戒，禍其遠矣。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-5","passageId":"wu-zi_ch-2_p-1","order":5,"canonicalText":"臣請論六國之俗：夫齊陳重而不堅，秦陳散而自鬭，楚陳整而不久，燕陳守而不走，三晉陳治而不用。","chunks":[["臣請論六國之俗：夫齊陳重而不堅，秦陳散而自鬭，楚陳整而不久，燕陳守而不走，三晉陳治而不用。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-6","passageId":"wu-zi_ch-2_p-1","order":6,"canonicalText":"夫齊性剛，其國富，君臣驕奢而簡於細民，其政寬而祿不均，一陳兩心，前重後輕，故重而不堅。","chunks":[["夫齊性剛，其國富，君臣驕奢而簡於細民，其政寬而祿不均，一陳兩心，前重後輕，故重而不堅。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-7","passageId":"wu-zi_ch-2_p-1","order":7,"canonicalText":"擊此之道，必三分之，獵其左右，脅而從之，其陳可壞。","chunks":[["擊此之道，必三分之，獵其左右，脅而從之，其陳可壞。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-8","passageId":"wu-zi_ch-2_p-1","order":8,"canonicalText":"秦性強，其地險，其政嚴，其賞罰信，其人不讓，皆有鬭心，故散而自戰。","chunks":[["秦性強，其地險，其政嚴，其賞罰信，其人不讓，皆有鬭心，故散而自戰。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-9","passageId":"wu-zi_ch-2_p-1","order":9,"canonicalText":"擊此之道，必先示之以利而引去之，士貪於得而離其將，乘乖獵散，設伏投機，其將可取。","chunks":[["擊此之道，必先示之以利而引去之，士貪於得而離其將，乘乖獵散，設伏投機，其將可取。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-10","passageId":"wu-zi_ch-2_p-1","order":10,"canonicalText":"楚性弱，其地廣，其政騷，其民疲，故整而不久。","chunks":[["楚性弱，其地廣，其政騷，其民疲，故整而不久。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-11","passageId":"wu-zi_ch-2_p-1","order":11,"canonicalText":"擊此之道，襲亂其屯，先奪其氣。","chunks":[["擊此之道，襲亂其屯，先奪其氣。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-12","passageId":"wu-zi_ch-2_p-1","order":12,"canonicalText":"輕進速退，弊而勞之，勿與戰爭，其軍可敗。","chunks":[["輕進速退，弊而勞之，勿與戰爭，其軍可敗。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-13","passageId":"wu-zi_ch-2_p-1","order":13,"canonicalText":"燕性愨，其民慎，好勇義，寡詐謀，故守而不走。","chunks":[["燕性愨，其民慎，好勇義，寡詐謀，故守而不走。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-14","passageId":"wu-zi_ch-2_p-1","order":14,"canonicalText":"擊此之道，觸而迫之，陵而遠之，馳而後之，則上疑而下懼，謹我車騎必避之路，其將可虜。","chunks":[["擊此之道，觸而迫之，陵而遠之，馳而後之，則上疑而下懼，謹我車騎必避之路，其將可虜。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-15","passageId":"wu-zi_ch-2_p-1","order":15,"canonicalText":"三晉者，中國也，其性和，其政平，其民疲於戰，習於兵，輕其將，薄其祿，士無死志，故治而不用。","chunks":[["三晉者，中國也，其性和，其政平，其民疲於戰，習於兵，輕其將，薄其祿，士無死志，故治而不用。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-16","passageId":"wu-zi_ch-2_p-1","order":16,"canonicalText":"擊此之道，阻陳而壓之，眾來則拒之，去則追之，以倦其師。","chunks":[["擊此之道，阻陳而壓之，眾來則拒之，去則追之，以倦其師。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-17","passageId":"wu-zi_ch-2_p-1","order":17,"canonicalText":"此其勢也。","chunks":[["此其勢也。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-18","passageId":"wu-zi_ch-2_p-1","order":18,"canonicalText":"然則一軍之中，必有虎賁之士；","chunks":[["然則一軍之中，必有虎賁之士；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-19","passageId":"wu-zi_ch-2_p-1","order":19,"canonicalText":"力輕扛鼎，足輕戎馬，搴旗斬將，必有能者。","chunks":[["力輕扛鼎，足輕戎馬，搴旗斬將，必有能者。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-20","passageId":"wu-zi_ch-2_p-1","order":20,"canonicalText":"若此之等，選而別之，愛而貴之，是謂軍命。","chunks":[["若此之等，選而別之，愛而貴之，是謂軍命。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-21","passageId":"wu-zi_ch-2_p-1","order":21,"canonicalText":"其有工用五兵、材力健疾、志在吞敵者，必加其爵列，可以決勝。","chunks":[["其有工用五兵、材力健疾、志在吞敵者，必加其爵列，可以決勝。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-22","passageId":"wu-zi_ch-2_p-1","order":22,"canonicalText":"厚其父母妻子，勸賞畏罰，此堅陳之士，可與持久。","chunks":[["厚其父母妻子，勸賞畏罰，此堅陳之士，可與持久。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-23","passageId":"wu-zi_ch-2_p-1","order":23,"canonicalText":"能審料此，可以擊倍。","chunks":[["能審料此，可以擊倍。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-24","passageId":"wu-zi_ch-2_p-1","order":24,"canonicalText":"」武侯曰：「善。","chunks":[["」武侯曰：「善。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-25","passageId":"wu-zi_ch-2_p-1","order":25,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-1","passageId":"wu-zi_ch-2_p-2","order":1,"canonicalText":"吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；","chunks":[["吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-2","passageId":"wu-zi_ch-2_p-2","order":2,"canonicalText":"二曰盛夏炎熱，晏興無間，行驅飢渴，務於取遠；","chunks":[["二曰盛夏炎熱，晏興無間，行驅飢渴，務於取遠；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-3","passageId":"wu-zi_ch-2_p-2","order":3,"canonicalText":"三曰師既淹久，糧食無有，百姓怨怒，祅祥數起，上不能止；","chunks":[["三曰師既淹久，糧食無有，百姓怨怒，祅祥數起，上不能止；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-4","passageId":"wu-zi_ch-2_p-2","order":4,"canonicalText":"四曰軍資既竭，薪芻既寡，天多陰雨，欲掠無所；","chunks":[["四曰軍資既竭，薪芻既寡，天多陰雨，欲掠無所；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-5","passageId":"wu-zi_ch-2_p-2","order":5,"canonicalText":"五曰徒眾不多，水地不利，人馬疾疫，四鄰不至；","chunks":[["五曰徒眾不多，水地不利，人馬疾疫，四鄰不至；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-6","passageId":"wu-zi_ch-2_p-2","order":6,"canonicalText":"六曰道遠日暮，士眾勞懼，倦而未食，解甲而息；","chunks":[["六曰道遠日暮，士眾勞懼，倦而未食，解甲而息；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-7","passageId":"wu-zi_ch-2_p-2","order":7,"canonicalText":"七曰將薄吏輕，士卒不固，三軍數驚，師徒無助；","chunks":[["七曰將薄吏輕，士卒不固，三軍數驚，師徒無助；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-8","passageId":"wu-zi_ch-2_p-2","order":8,"canonicalText":"八曰陳而未定，舍而未畢，行阪涉險，半隱半出。","chunks":[["八曰陳而未定，舍而未畢，行阪涉險，半隱半出。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-9","passageId":"wu-zi_ch-2_p-2","order":9,"canonicalText":"諸如此者，擊之勿疑。","chunks":[["諸如此者，擊之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-10","passageId":"wu-zi_ch-2_p-2","order":10,"canonicalText":"有不佔而避之者六：一曰土地廣大，人民富眾；","chunks":[["有不佔而避之者六：一曰土地廣大，人民富眾；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-11","passageId":"wu-zi_ch-2_p-2","order":11,"canonicalText":"二曰上愛其下，惠施流佈；","chunks":[["二曰上愛其下，惠施流佈；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-12","passageId":"wu-zi_ch-2_p-2","order":12,"canonicalText":"三曰賞信刑察，發必得時；","chunks":[["三曰賞信刑察，發必得時；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-13","passageId":"wu-zi_ch-2_p-2","order":13,"canonicalText":"四曰陳功居列，任賢使能；","chunks":[["四曰陳功居列，任賢使能；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-14","passageId":"wu-zi_ch-2_p-2","order":14,"canonicalText":"五曰師徒之眾，兵甲之精；","chunks":[["五曰師徒之眾，兵甲之精；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-15","passageId":"wu-zi_ch-2_p-2","order":15,"canonicalText":"六曰四鄰之助，大國之援。","chunks":[["六曰四鄰之助，大國之援。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-16","passageId":"wu-zi_ch-2_p-2","order":16,"canonicalText":"凡此不如敵人，避之勿疑。","chunks":[["凡此不如敵人，避之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-17","passageId":"wu-zi_ch-2_p-2","order":17,"canonicalText":"所謂見可而進，知難而退也。","chunks":[["所謂見可而進，知難而退也。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-18","passageId":"wu-zi_ch-2_p-2","order":18,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-1","passageId":"wu-zi_ch-2_p-3","order":1,"canonicalText":"武侯問曰：「吾欲觀敵之外以知其內，察其進以知其止，以定勝負，可得聞乎？","chunks":[["武侯問曰：「吾欲觀敵之外以知其內，察其進以知其止，以定勝負，可得聞乎？","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-2","passageId":"wu-zi_ch-2_p-3","order":2,"canonicalText":"」起對曰：「敵人之來，蕩蕩無慮，旌旗煩亂，人馬數顧，一可擊十，必使無措。","chunks":[["」起對曰：「敵人之來，蕩蕩無慮，旌旗煩亂，人馬數顧，一可擊十，必使無措。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-3","passageId":"wu-zi_ch-2_p-3","order":3,"canonicalText":"諸侯大會，君臣未和，溝壘未成，禁令未施，三軍匈匈，欲前不能，欲去不敢，以半擊倍，百戰不殆。","chunks":[["諸侯大會，君臣未和，溝壘未成，禁令未施，三軍匈匈，欲前不能，欲去不敢，以半擊倍，百戰不殆。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-4","passageId":"wu-zi_ch-2_p-3","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-1","passageId":"wu-zi_ch-2_p-4","order":1,"canonicalText":"武侯問敵必可擊之道。","chunks":[["武侯問敵必可擊之道。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-2","passageId":"wu-zi_ch-2_p-4","order":2,"canonicalText":"起對曰：「用兵必須審敵虛實而趨其危。","chunks":[["起對曰：「用兵必須審敵虛實而趨其危。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-3","passageId":"wu-zi_ch-2_p-4","order":3,"canonicalText":"敵人遠來新至、行列未定可擊，既食未設備可擊，奔走可擊，勤勞可擊，未得地利可擊，失時不從可擊，旌旗亂動可擊，涉長道後行未息可擊，涉水半渡可擊，險道狹路可擊，陳數移動可擊，將離士卒可擊，心怖可擊。","chunks":[["敵人遠來新至、行列未定可擊，既食未設備可擊，奔走可擊，勤勞可擊，未得地利可擊，失時不從可擊，旌旗亂動可擊，涉長道後行未息可擊，涉水半渡可擊，險道狹路可擊，陳數移動可擊，將離士卒可擊，心怖可擊。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-4","passageId":"wu-zi_ch-2_p-4","order":4,"canonicalText":"凡若此者，選銳衝之，分兵繼之，急擊勿疑。","chunks":[["凡若此者，選銳衝之，分兵繼之，急擊勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-5","passageId":"wu-zi_ch-2_p-4","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-1","passageId":"wu-zi_ch-3_p-1","order":1,"canonicalText":"武侯問曰：「進兵之道何先？","chunks":[["武侯問曰：「進兵之道何先？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-2","passageId":"wu-zi_ch-3_p-1","order":2,"canonicalText":"」起對曰：「先明四輕、二重、一信。","chunks":[["」起對曰：「先明四輕、二重、一信。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-3","passageId":"wu-zi_ch-3_p-1","order":3,"canonicalText":"」曰：「何謂也？","chunks":[["」曰：「何謂也？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-4","passageId":"wu-zi_ch-3_p-1","order":4,"canonicalText":"」對曰：「使地輕馬，馬輕車，車輕人，人輕戰。","chunks":[["」對曰：「使地輕馬，馬輕車，車輕人，人輕戰。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-5","passageId":"wu-zi_ch-3_p-1","order":5,"canonicalText":"明知陰陽，則地輕馬。","chunks":[["明知陰陽，則地輕馬。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-6","passageId":"wu-zi_ch-3_p-1","order":6,"canonicalText":"芻秣以時，則馬輕車。","chunks":[["芻秣以時，則馬輕車。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-7","passageId":"wu-zi_ch-3_p-1","order":7,"canonicalText":"膏鐧有餘，則車輕人。","chunks":[["膏鐧有餘，則車輕人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-8","passageId":"wu-zi_ch-3_p-1","order":8,"canonicalText":"鋒銳甲堅，則人輕戰。","chunks":[["鋒銳甲堅，則人輕戰。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-9","passageId":"wu-zi_ch-3_p-1","order":9,"canonicalText":"進有重賞，退有重刑。","chunks":[["進有重賞，退有重刑。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-10","passageId":"wu-zi_ch-3_p-1","order":10,"canonicalText":"行之以信。","chunks":[["行之以信。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-11","passageId":"wu-zi_ch-3_p-1","order":11,"canonicalText":"令制遠，此勝之主也。","chunks":[["令制遠，此勝之主也。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-12","passageId":"wu-zi_ch-3_p-1","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-1","passageId":"wu-zi_ch-3_p-2","order":1,"canonicalText":"武侯問曰：「兵何以為勝？","chunks":[["武侯問曰：「兵何以為勝？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-2","passageId":"wu-zi_ch-3_p-2","order":2,"canonicalText":"」起對曰：「以治為勝。","chunks":[["」起對曰：「以治為勝。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-3","passageId":"wu-zi_ch-3_p-2","order":3,"canonicalText":"」又問曰：「不在眾寡？","chunks":[["」又問曰：「不在眾寡？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-4","passageId":"wu-zi_ch-3_p-2","order":4,"canonicalText":"」對曰：「若法令不明，賞罰不信，金之不止，鼓之不進，雖有百萬，何益於用。","chunks":[["」對曰：「若法令不明，賞罰不信，金之不止，鼓之不進，雖有百萬，何益於用。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-5","passageId":"wu-zi_ch-3_p-2","order":5,"canonicalText":"所謂治者，居則有禮，動則有威，進不可當，退不可追，前卻有節，左右應麾，雖絕成陳，雖散成行。","chunks":[["所謂治者，居則有禮，動則有威，進不可當，退不可追，前卻有節，左右應麾，雖絕成陳，雖散成行。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-6","passageId":"wu-zi_ch-3_p-2","order":6,"canonicalText":"與之安，與之危，其眾可合而不可離，可用而不可疲，投之所往，天下莫當，名曰父子之兵。","chunks":[["與之安，與之危，其眾可合而不可離，可用而不可疲，投之所往，天下莫當，名曰父子之兵。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-7","passageId":"wu-zi_ch-3_p-2","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-1","passageId":"wu-zi_ch-3_p-3","order":1,"canonicalText":"吳子曰：「凡行軍之道，無犯進止之節，無失飲食之適，無絕人馬之力。","chunks":[["吳子曰：「凡行軍之道，無犯進止之節，無失飲食之適，無絕人馬之力。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-2","passageId":"wu-zi_ch-3_p-3","order":2,"canonicalText":"此三者，所以任其上令。","chunks":[["此三者，所以任其上令。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-3","passageId":"wu-zi_ch-3_p-3","order":3,"canonicalText":"任其上令，則治之所由生也。","chunks":[["任其上令，則治之所由生也。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-4","passageId":"wu-zi_ch-3_p-3","order":4,"canonicalText":"若進止不度，飲食不適，馬疲人倦而不解舍，所以不任其上令。","chunks":[["若進止不度，飲食不適，馬疲人倦而不解舍，所以不任其上令。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-5","passageId":"wu-zi_ch-3_p-3","order":5,"canonicalText":"上令既廢，以居則亂，以戰則敗。","chunks":[["上令既廢，以居則亂，以戰則敗。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-6","passageId":"wu-zi_ch-3_p-3","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-1","passageId":"wu-zi_ch-3_p-4","order":1,"canonicalText":"吳子曰：「凡兵戰之場，立屍之地。","chunks":[["吳子曰：「凡兵戰之場，立屍之地。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-2","passageId":"wu-zi_ch-3_p-4","order":2,"canonicalText":"必死則生，幸生則死。","chunks":[["必死則生，幸生則死。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-3","passageId":"wu-zi_ch-3_p-4","order":3,"canonicalText":"其善將者，如坐漏船之中，伏燒屋之下，使智者不及謀，勇者不及怒，受敵可也。","chunks":[["其善將者，如坐漏船之中，伏燒屋之下，使智者不及謀，勇者不及怒，受敵可也。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-4","passageId":"wu-zi_ch-3_p-4","order":4,"canonicalText":"故曰：用兵之害，猶豫最大；","chunks":[["故曰：用兵之害，猶豫最大；","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-5","passageId":"wu-zi_ch-3_p-4","order":5,"canonicalText":"三軍之災，生於狐疑。","chunks":[["三軍之災，生於狐疑。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-6","passageId":"wu-zi_ch-3_p-4","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-1","passageId":"wu-zi_ch-3_p-5","order":1,"canonicalText":"吳子曰：「夫人當死其所不能，敗其所不便。","chunks":[["吳子曰：「夫人當死其所不能，敗其所不便。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-2","passageId":"wu-zi_ch-3_p-5","order":2,"canonicalText":"故用兵之法，教戒為先。","chunks":[["故用兵之法，教戒為先。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-3","passageId":"wu-zi_ch-3_p-5","order":3,"canonicalText":"一人學戰，教成十人。","chunks":[["一人學戰，教成十人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-4","passageId":"wu-zi_ch-3_p-5","order":4,"canonicalText":"十人學戰，教成百人。","chunks":[["十人學戰，教成百人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-5","passageId":"wu-zi_ch-3_p-5","order":5,"canonicalText":"百人學戰，教成千人。","chunks":[["百人學戰，教成千人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-6","passageId":"wu-zi_ch-3_p-5","order":6,"canonicalText":"千人學戰，教成萬人。","chunks":[["千人學戰，教成萬人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-7","passageId":"wu-zi_ch-3_p-5","order":7,"canonicalText":"萬人學戰，教成三軍。","chunks":[["萬人學戰，教成三軍。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-8","passageId":"wu-zi_ch-3_p-5","order":8,"canonicalText":"以近待遠，以佚待勞，以飽待飢。","chunks":[["以近待遠，以佚待勞，以飽待飢。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-9","passageId":"wu-zi_ch-3_p-5","order":9,"canonicalText":"圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。","chunks":[["圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-10","passageId":"wu-zi_ch-3_p-5","order":10,"canonicalText":"每變皆習，乃授其兵。","chunks":[["每變皆習，乃授其兵。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-11","passageId":"wu-zi_ch-3_p-5","order":11,"canonicalText":"是謂將事。","chunks":[["是謂將事。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-12","passageId":"wu-zi_ch-3_p-5","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-1","passageId":"wu-zi_ch-3_p-6","order":1,"canonicalText":"吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。","chunks":[["吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-2","passageId":"wu-zi_ch-3_p-6","order":2,"canonicalText":"鄉里相比，什伍相保。","chunks":[["鄉里相比，什伍相保。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-3","passageId":"wu-zi_ch-3_p-6","order":3,"canonicalText":"一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。","chunks":[["一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-4","passageId":"wu-zi_ch-3_p-6","order":4,"canonicalText":"聞鼓聲合，然後舉旗。","chunks":[["聞鼓聲合，然後舉旗。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-5","passageId":"wu-zi_ch-3_p-6","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-1","passageId":"wu-zi_ch-3_p-7","order":1,"canonicalText":"武侯問曰：「三軍進止。","chunks":[["武侯問曰：「三軍進止。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-2","passageId":"wu-zi_ch-3_p-7","order":2,"canonicalText":"豈有道乎？","chunks":[["豈有道乎？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-3","passageId":"wu-zi_ch-3_p-7","order":3,"canonicalText":"」起對曰：「無當天竈，無當龍頭。","chunks":[["」起對曰：「無當天竈，無當龍頭。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-4","passageId":"wu-zi_ch-3_p-7","order":4,"canonicalText":"天竈者，大谷之口。","chunks":[["天竈者，大谷之口。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-5","passageId":"wu-zi_ch-3_p-7","order":5,"canonicalText":"龍頭者，大山之端。","chunks":[["龍頭者，大山之端。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-6","passageId":"wu-zi_ch-3_p-7","order":6,"canonicalText":"必左青龍，右白虎，前朱雀，後玄武，招搖在上，從事於下。","chunks":[["必左青龍，右白虎，前朱雀，後玄武，招搖在上，從事於下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-7","passageId":"wu-zi_ch-3_p-7","order":7,"canonicalText":"將戰之時，審候風所從來。","chunks":[["將戰之時，審候風所從來。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-8","passageId":"wu-zi_ch-3_p-7","order":8,"canonicalText":"風順致呼而從之，風逆堅陳以待之。","chunks":[["風順致呼而從之，風逆堅陳以待之。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-9","passageId":"wu-zi_ch-3_p-7","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-1","passageId":"wu-zi_ch-3_p-8","order":1,"canonicalText":"武侯問曰：「凡畜卒騎，豈有方乎？","chunks":[["武侯問曰：「凡畜卒騎，豈有方乎？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-2","passageId":"wu-zi_ch-3_p-8","order":2,"canonicalText":"」起對曰：「夫馬必安其處所，適其水草，節其飢飽。","chunks":[["」起對曰：「夫馬必安其處所，適其水草，節其飢飽。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-3","passageId":"wu-zi_ch-3_p-8","order":3,"canonicalText":"冬則溫燒，夏則涼廡。","chunks":[["冬則溫燒，夏則涼廡。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-4","passageId":"wu-zi_ch-3_p-8","order":4,"canonicalText":"刻剔毛鬣，謹落四下。","chunks":[["刻剔毛鬣，謹落四下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-5","passageId":"wu-zi_ch-3_p-8","order":5,"canonicalText":"戢其耳目，無令驚駭。","chunks":[["戢其耳目，無令驚駭。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-6","passageId":"wu-zi_ch-3_p-8","order":6,"canonicalText":"習其馳逐，閑其進止。","chunks":[["習其馳逐，閑其進止。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-7","passageId":"wu-zi_ch-3_p-8","order":7,"canonicalText":"人馬相親，然後可使。","chunks":[["人馬相親，然後可使。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-8","passageId":"wu-zi_ch-3_p-8","order":8,"canonicalText":"車騎之具，鞍、勒、銜、轡，必令完堅。","chunks":[["車騎之具，鞍、勒、銜、轡，必令完堅。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-9","passageId":"wu-zi_ch-3_p-8","order":9,"canonicalText":"凡馬不傷於末，必傷於始；","chunks":[["凡馬不傷於末，必傷於始；","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-10","passageId":"wu-zi_ch-3_p-8","order":10,"canonicalText":"不傷於飢，必傷於飽。","chunks":[["不傷於飢，必傷於飽。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-11","passageId":"wu-zi_ch-3_p-8","order":11,"canonicalText":"日暮道遠，必數上下。","chunks":[["日暮道遠，必數上下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-12","passageId":"wu-zi_ch-3_p-8","order":12,"canonicalText":"寧勞於人，慎無勞馬。","chunks":[["寧勞於人，慎無勞馬。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-13","passageId":"wu-zi_ch-3_p-8","order":13,"canonicalText":"常令有餘，備敵覆我。","chunks":[["常令有餘，備敵覆我。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-14","passageId":"wu-zi_ch-3_p-8","order":14,"canonicalText":"能明此者，橫行天下。","chunks":[["能明此者，橫行天下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-15","passageId":"wu-zi_ch-3_p-8","order":15,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-1","passageId":"wu-zi_ch-4_p-1","order":1,"canonicalText":"吳子曰：「夫總文武者，軍之將也。","chunks":[["吳子曰：「夫總文武者，軍之將也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-2","passageId":"wu-zi_ch-4_p-1","order":2,"canonicalText":"兼剛柔者，兵之事也。","chunks":[["兼剛柔者，兵之事也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-3","passageId":"wu-zi_ch-4_p-1","order":3,"canonicalText":"凡人論將，常觀於勇。","chunks":[["凡人論將，常觀於勇。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-4","passageId":"wu-zi_ch-4_p-1","order":4,"canonicalText":"勇之於將，乃數分之一爾。","chunks":[["勇之於將，乃數分之一爾。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-5","passageId":"wu-zi_ch-4_p-1","order":5,"canonicalText":"夫勇者必輕合，輕合而不知利，未可也。","chunks":[["夫勇者必輕合，輕合而不知利，未可也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-6","passageId":"wu-zi_ch-4_p-1","order":6,"canonicalText":"故將之所慎者五：一曰理，二曰備，三曰果，四曰戒，五曰約。","chunks":[["故將之所慎者五：一曰理，二曰備，三曰果，四曰戒，五曰約。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-7","passageId":"wu-zi_ch-4_p-1","order":7,"canonicalText":"理者，治眾如治寡。","chunks":[["理者，治眾如治寡。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-8","passageId":"wu-zi_ch-4_p-1","order":8,"canonicalText":"備者，出門如見敵。","chunks":[["備者，出門如見敵。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-9","passageId":"wu-zi_ch-4_p-1","order":9,"canonicalText":"果者，臨敵不懷生。","chunks":[["果者，臨敵不懷生。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-10","passageId":"wu-zi_ch-4_p-1","order":10,"canonicalText":"戒者，雖克如始戰。","chunks":[["戒者，雖克如始戰。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-11","passageId":"wu-zi_ch-4_p-1","order":11,"canonicalText":"約者，法令省而不煩。","chunks":[["約者，法令省而不煩。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-12","passageId":"wu-zi_ch-4_p-1","order":12,"canonicalText":"受命而不辭，敵破而後言返，將之禮也。","chunks":[["受命而不辭，敵破而後言返，將之禮也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-13","passageId":"wu-zi_ch-4_p-1","order":13,"canonicalText":"故師出之日，有死之榮，無生之辱。","chunks":[["故師出之日，有死之榮，無生之辱。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-14","passageId":"wu-zi_ch-4_p-1","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-1","passageId":"wu-zi_ch-4_p-2","order":1,"canonicalText":"吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。","chunks":[["吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-2","passageId":"wu-zi_ch-4_p-2","order":2,"canonicalText":"三軍之眾，百萬之師，張設輕重，在於一人，是謂氣機。","chunks":[["三軍之眾，百萬之師，張設輕重，在於一人，是謂氣機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-3","passageId":"wu-zi_ch-4_p-2","order":3,"canonicalText":"路狹道險，名山大塞，十夫所守，千夫不過，是謂地機。","chunks":[["路狹道險，名山大塞，十夫所守，千夫不過，是謂地機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-4","passageId":"wu-zi_ch-4_p-2","order":4,"canonicalText":"善行間諜，輕兵往來，分散其眾，使其君臣相怨，上下相咎，是謂事機。","chunks":[["善行間諜，輕兵往來，分散其眾，使其君臣相怨，上下相咎，是謂事機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-5","passageId":"wu-zi_ch-4_p-2","order":5,"canonicalText":"車堅管轄，舟利櫓楫，士習戰陳，馬閑馳逐，是謂力機。","chunks":[["車堅管轄，舟利櫓楫，士習戰陳，馬閑馳逐，是謂力機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-6","passageId":"wu-zi_ch-4_p-2","order":6,"canonicalText":"知此四者，乃可為將。","chunks":[["知此四者，乃可為將。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-7","passageId":"wu-zi_ch-4_p-2","order":7,"canonicalText":"然其威、德、仁、勇，必足以率下安眾，怖敵決疑。","chunks":[["然其威、德、仁、勇，必足以率下安眾，怖敵決疑。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-8","passageId":"wu-zi_ch-4_p-2","order":8,"canonicalText":"施令而下不犯，所在寇不敢敵。","chunks":[["施令而下不犯，所在寇不敢敵。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-9","passageId":"wu-zi_ch-4_p-2","order":9,"canonicalText":"得之國強，去之國亡。","chunks":[["得之國強，去之國亡。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-10","passageId":"wu-zi_ch-4_p-2","order":10,"canonicalText":"是謂良將。","chunks":[["是謂良將。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-11","passageId":"wu-zi_ch-4_p-2","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-1","passageId":"wu-zi_ch-4_p-3","order":1,"canonicalText":"吳子曰：「夫鼙鼓金鐸，所以威耳。","chunks":[["吳子曰：「夫鼙鼓金鐸，所以威耳。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-2","passageId":"wu-zi_ch-4_p-3","order":2,"canonicalText":"旌旗麾幟，所以威目。","chunks":[["旌旗麾幟，所以威目。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-3","passageId":"wu-zi_ch-4_p-3","order":3,"canonicalText":"禁令刑罰，所以威心。","chunks":[["禁令刑罰，所以威心。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-4","passageId":"wu-zi_ch-4_p-3","order":4,"canonicalText":"耳威於聲，不可不清。","chunks":[["耳威於聲，不可不清。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-5","passageId":"wu-zi_ch-4_p-3","order":5,"canonicalText":"目威於色，不可不明。","chunks":[["目威於色，不可不明。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-6","passageId":"wu-zi_ch-4_p-3","order":6,"canonicalText":"心威於刑，不可不嚴。","chunks":[["心威於刑，不可不嚴。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-7","passageId":"wu-zi_ch-4_p-3","order":7,"canonicalText":"三者不立，雖有其國，必敗於敵。","chunks":[["三者不立，雖有其國，必敗於敵。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-8","passageId":"wu-zi_ch-4_p-3","order":8,"canonicalText":"故曰：將之所麾，莫不從移；","chunks":[["故曰：將之所麾，莫不從移；","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-9","passageId":"wu-zi_ch-4_p-3","order":9,"canonicalText":"將之所指，莫不前死。","chunks":[["將之所指，莫不前死。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-10","passageId":"wu-zi_ch-4_p-3","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-1","passageId":"wu-zi_ch-4_p-4","order":1,"canonicalText":"吳子曰：「凡戰之要，必先佔其將而察其才。","chunks":[["吳子曰：「凡戰之要，必先佔其將而察其才。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-2","passageId":"wu-zi_ch-4_p-4","order":2,"canonicalText":"因形用權，則不勞而功舉。","chunks":[["因形用權，則不勞而功舉。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-3","passageId":"wu-zi_ch-4_p-4","order":3,"canonicalText":"其將愚而信人，可詐而誘；","chunks":[["其將愚而信人，可詐而誘；","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-4","passageId":"wu-zi_ch-4_p-4","order":4,"canonicalText":"貪而忽名，可貨而賂；","chunks":[["貪而忽名，可貨而賂；","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-5","passageId":"wu-zi_ch-4_p-4","order":5,"canonicalText":"輕變無謀，可勞而困。","chunks":[["輕變無謀，可勞而困。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-6","passageId":"wu-zi_ch-4_p-4","order":6,"canonicalText":"上富而驕，下貧而怨，可離而間。","chunks":[["上富而驕，下貧而怨，可離而間。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-7","passageId":"wu-zi_ch-4_p-4","order":7,"canonicalText":"進退多疑，其眾無依，可震而走。","chunks":[["進退多疑，其眾無依，可震而走。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-8","passageId":"wu-zi_ch-4_p-4","order":8,"canonicalText":"士輕其將而有歸志，塞易開險，可邀而取。","chunks":[["士輕其將而有歸志，塞易開險，可邀而取。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-9","passageId":"wu-zi_ch-4_p-4","order":9,"canonicalText":"進道易，退道難，可來而前。","chunks":[["進道易，退道難，可來而前。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-10","passageId":"wu-zi_ch-4_p-4","order":10,"canonicalText":"進道險，退道易，可薄而擊。","chunks":[["進道險，退道易，可薄而擊。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-11","passageId":"wu-zi_ch-4_p-4","order":11,"canonicalText":"居軍下濕，水無所通，霖雨數至，可灌而沈。","chunks":[["居軍下濕，水無所通，霖雨數至，可灌而沈。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-12","passageId":"wu-zi_ch-4_p-4","order":12,"canonicalText":"居軍荒澤，草楚幽穢，風飆數至，可焚而滅。","chunks":[["居軍荒澤，草楚幽穢，風飆數至，可焚而滅。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-13","passageId":"wu-zi_ch-4_p-4","order":13,"canonicalText":"停久不移，將士懈怠，其軍不備，可潛而襲。","chunks":[["停久不移，將士懈怠，其軍不備，可潛而襲。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-14","passageId":"wu-zi_ch-4_p-4","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-1","passageId":"wu-zi_ch-4_p-5","order":1,"canonicalText":"武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？","chunks":[["武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-2","passageId":"wu-zi_ch-4_p-5","order":2,"canonicalText":"」起對曰：「令賤而勇者，將輕銳以嘗之。","chunks":[["」起對曰：「令賤而勇者，將輕銳以嘗之。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-3","passageId":"wu-zi_ch-4_p-5","order":3,"canonicalText":"務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。","chunks":[["務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-4","passageId":"wu-zi_ch-4_p-5","order":4,"canonicalText":"若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。","chunks":[["若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-5","passageId":"wu-zi_ch-4_p-5","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-1","passageId":"wu-zi_ch-5_p-1","order":1,"canonicalText":"武侯問曰：「車堅馬良，將勇兵強，卒遇敵人，亂而失行，則如之何？","chunks":[["武侯問曰：「車堅馬良，將勇兵強，卒遇敵人，亂而失行，則如之何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-2","passageId":"wu-zi_ch-5_p-1","order":2,"canonicalText":"」起對曰：「凡戰之法，晝以旌旗旛麾為節，夜以金鼓笳笛為節。","chunks":[["」起對曰：「凡戰之法，晝以旌旗旛麾為節，夜以金鼓笳笛為節。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-3","passageId":"wu-zi_ch-5_p-1","order":3,"canonicalText":"麾左而左，麾右而右。","chunks":[["麾左而左，麾右而右。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-4","passageId":"wu-zi_ch-5_p-1","order":4,"canonicalText":"鼓之則進，金之則止。","chunks":[["鼓之則進，金之則止。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-5","passageId":"wu-zi_ch-5_p-1","order":5,"canonicalText":"二吹而行，再吹而聚，不從令者誅。","chunks":[["二吹而行，再吹而聚，不從令者誅。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-6","passageId":"wu-zi_ch-5_p-1","order":6,"canonicalText":"三軍服威，士卒用命，則戰無彊敵，攻無堅陳矣。","chunks":[["三軍服威，士卒用命，則戰無彊敵，攻無堅陳矣。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-7","passageId":"wu-zi_ch-5_p-1","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-1","passageId":"wu-zi_ch-5_p-2","order":1,"canonicalText":"武侯問曰：「若敵眾我寡，為之柰何？","chunks":[["武侯問曰：「若敵眾我寡，為之柰何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-2","passageId":"wu-zi_ch-5_p-2","order":2,"canonicalText":"」起對曰：「避之於易，邀之於阨。","chunks":[["」起對曰：「避之於易，邀之於阨。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-3","passageId":"wu-zi_ch-5_p-2","order":3,"canonicalText":"故曰：以一擊十，莫善於阨；","chunks":[["故曰：以一擊十，莫善於阨；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-4","passageId":"wu-zi_ch-5_p-2","order":4,"canonicalText":"以十擊百，莫善於險；","chunks":[["以十擊百，莫善於險；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-5","passageId":"wu-zi_ch-5_p-2","order":5,"canonicalText":"以千擊萬，莫善於阻。","chunks":[["以千擊萬，莫善於阻。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-6","passageId":"wu-zi_ch-5_p-2","order":6,"canonicalText":"今有少年卒起，擊金鳴鼓於阨路，雖有大眾，莫不驚動。","chunks":[["今有少年卒起，擊金鳴鼓於阨路，雖有大眾，莫不驚動。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-7","passageId":"wu-zi_ch-5_p-2","order":7,"canonicalText":"故曰：用眾者務易，用少者務隘。","chunks":[["故曰：用眾者務易，用少者務隘。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-8","passageId":"wu-zi_ch-5_p-2","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-1","passageId":"wu-zi_ch-5_p-3","order":1,"canonicalText":"武侯問曰：「有師甚眾，既武且勇；","chunks":[["武侯問曰：「有師甚眾，既武且勇；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-2","passageId":"wu-zi_ch-5_p-3","order":2,"canonicalText":"背大險阻，右山左水；","chunks":[["背大險阻，右山左水；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-3","passageId":"wu-zi_ch-5_p-3","order":3,"canonicalText":"深溝高壘，守以彊弩；","chunks":[["深溝高壘，守以彊弩；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-4","passageId":"wu-zi_ch-5_p-3","order":4,"canonicalText":"退如山移，進如風雨，糧食又多。","chunks":[["退如山移，進如風雨，糧食又多。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-5","passageId":"wu-zi_ch-5_p-3","order":5,"canonicalText":"難與長守。","chunks":[["難與長守。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-6","passageId":"wu-zi_ch-5_p-3","order":6,"canonicalText":"」對曰：「大哉問乎！","chunks":[["」對曰：「大哉問乎！","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-7","passageId":"wu-zi_ch-5_p-3","order":7,"canonicalText":"非此車騎之力，聖人之謀也。","chunks":[["非此車騎之力，聖人之謀也。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-8","passageId":"wu-zi_ch-5_p-3","order":8,"canonicalText":"能備千乘萬騎，兼之徒步，分為五軍，各軍一衢。","chunks":[["能備千乘萬騎，兼之徒步，分為五軍，各軍一衢。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-9","passageId":"wu-zi_ch-5_p-3","order":9,"canonicalText":"夫五軍五衢，敵人必惑，莫之所加。","chunks":[["夫五軍五衢，敵人必惑，莫之所加。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-10","passageId":"wu-zi_ch-5_p-3","order":10,"canonicalText":"敵人若堅守以固其兵，急行間諜以觀其慮。","chunks":[["敵人若堅守以固其兵，急行間諜以觀其慮。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-11","passageId":"wu-zi_ch-5_p-3","order":11,"canonicalText":"彼聽吾說，解之而去。","chunks":[["彼聽吾說，解之而去。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-12","passageId":"wu-zi_ch-5_p-3","order":12,"canonicalText":"不聽吾說，斬使焚書，分為五戰。","chunks":[["不聽吾說，斬使焚書，分為五戰。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-13","passageId":"wu-zi_ch-5_p-3","order":13,"canonicalText":"戰勝勿追，不勝疾歸。","chunks":[["戰勝勿追，不勝疾歸。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-14","passageId":"wu-zi_ch-5_p-3","order":14,"canonicalText":"如是佯北，安行疾鬭，一結其前，一絕其後。","chunks":[["如是佯北，安行疾鬭，一結其前，一絕其後。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-15","passageId":"wu-zi_ch-5_p-3","order":15,"canonicalText":"兩軍𠾑枚，或左或右，而襲其處。","chunks":[["兩軍𠾑枚，或左或右，而襲其處。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-16","passageId":"wu-zi_ch-5_p-3","order":16,"canonicalText":"五軍交至，必有其力。","chunks":[["五軍交至，必有其力。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-17","passageId":"wu-zi_ch-5_p-3","order":17,"canonicalText":"此擊彊之道也。","chunks":[["此擊彊之道也。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-18","passageId":"wu-zi_ch-5_p-3","order":18,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-1","passageId":"wu-zi_ch-5_p-4","order":1,"canonicalText":"武侯問曰：「敵近而薄我，欲去無路，我眾甚懼，為之柰何？","chunks":[["武侯問曰：「敵近而薄我，欲去無路，我眾甚懼，為之柰何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-2","passageId":"wu-zi_ch-5_p-4","order":2,"canonicalText":"」對曰：「為此之術，若我眾彼寡，各分而乘之。","chunks":[["」對曰：「為此之術，若我眾彼寡，各分而乘之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-3","passageId":"wu-zi_ch-5_p-4","order":3,"canonicalText":"彼眾我寡，以方從之。","chunks":[["彼眾我寡，以方從之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-4","passageId":"wu-zi_ch-5_p-4","order":4,"canonicalText":"從之無息，雖眾可服。","chunks":[["從之無息，雖眾可服。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-5","passageId":"wu-zi_ch-5_p-4","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-1","passageId":"wu-zi_ch-5_p-5","order":1,"canonicalText":"武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？","chunks":[["武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-2","passageId":"wu-zi_ch-5_p-5","order":2,"canonicalText":"」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。","chunks":[["」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-3","passageId":"wu-zi_ch-5_p-5","order":3,"canonicalText":"若高山深谷，卒然相遇，必先鼓譟而乘之。","chunks":[["若高山深谷，卒然相遇，必先鼓譟而乘之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-4","passageId":"wu-zi_ch-5_p-5","order":4,"canonicalText":"進弓與弩，且射且虜。","chunks":[["進弓與弩，且射且虜。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-5","passageId":"wu-zi_ch-5_p-5","order":5,"canonicalText":"審察其政，亂則擊之勿疑。","chunks":[["審察其政，亂則擊之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-6","passageId":"wu-zi_ch-5_p-5","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-1","passageId":"wu-zi_ch-5_p-6","order":1,"canonicalText":"武侯問曰：「左右高山，地甚狹迫，卒遇敵人，擊之不敢，去之不得，為之奈何？","chunks":[["武侯問曰：「左右高山，地甚狹迫，卒遇敵人，擊之不敢，去之不得，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-2","passageId":"wu-zi_ch-5_p-6","order":2,"canonicalText":"」起對曰：「此謂谷戰，雖眾不用。","chunks":[["」起對曰：「此謂谷戰，雖眾不用。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-3","passageId":"wu-zi_ch-5_p-6","order":3,"canonicalText":"募吾材士與敵相當，輕足利兵以為前行，分車列騎隱於四旁，相去數裏，無見其兵，敵必堅陳，進退不敢。","chunks":[["募吾材士與敵相當，輕足利兵以為前行，分車列騎隱於四旁，相去數裏，無見其兵，敵必堅陳，進退不敢。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-4","passageId":"wu-zi_ch-5_p-6","order":4,"canonicalText":"於是出旌列旆，行出山外營之，敵人必懼。","chunks":[["於是出旌列旆，行出山外營之，敵人必懼。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-5","passageId":"wu-zi_ch-5_p-6","order":5,"canonicalText":"車騎挑之，勿令得休。","chunks":[["車騎挑之，勿令得休。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-6","passageId":"wu-zi_ch-5_p-6","order":6,"canonicalText":"此谷戰之法也。","chunks":[["此谷戰之法也。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-7","passageId":"wu-zi_ch-5_p-6","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-1","passageId":"wu-zi_ch-5_p-7","order":1,"canonicalText":"武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？","chunks":[["武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-2","passageId":"wu-zi_ch-5_p-7","order":2,"canonicalText":"」起對曰：「此謂水戰，無用車騎，且留其傍。","chunks":[["」起對曰：「此謂水戰，無用車騎，且留其傍。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-3","passageId":"wu-zi_ch-5_p-7","order":3,"canonicalText":"登高四望，必得水情。","chunks":[["登高四望，必得水情。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-4","passageId":"wu-zi_ch-5_p-7","order":4,"canonicalText":"知其廣狹，盡其淺深，乃可為奇以勝之。","chunks":[["知其廣狹，盡其淺深，乃可為奇以勝之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-5","passageId":"wu-zi_ch-5_p-7","order":5,"canonicalText":"敵若絕水，半渡而薄之。","chunks":[["敵若絕水，半渡而薄之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-6","passageId":"wu-zi_ch-5_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-1","passageId":"wu-zi_ch-5_p-8","order":1,"canonicalText":"武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？","chunks":[["武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-2","passageId":"wu-zi_ch-5_p-8","order":2,"canonicalText":"」起對曰：「凡用車者，陰濕則停，陽燥則起；","chunks":[["」起對曰：「凡用車者，陰濕則停，陽燥則起；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-3","passageId":"wu-zi_ch-5_p-8","order":3,"canonicalText":"貴高賤下，馳其強車；","chunks":[["貴高賤下，馳其強車；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-4","passageId":"wu-zi_ch-5_p-8","order":4,"canonicalText":"若進若止，必從其道。","chunks":[["若進若止，必從其道。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-5","passageId":"wu-zi_ch-5_p-8","order":5,"canonicalText":"敵人若起，必逐其跡。","chunks":[["敵人若起，必逐其跡。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-6","passageId":"wu-zi_ch-5_p-8","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-9_s-1","passageId":"wu-zi_ch-5_p-9","order":1,"canonicalText":"武侯問曰：「暴寇卒來，掠吾田野，取吾牛羊，則如之何？","chunks":[["武侯問曰：「暴寇卒來，掠吾田野，取吾牛羊，則如之何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-9_s-2","passageId":"wu-zi_ch-5_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-1","passageId":"wu-zi_ch-5_p-10","order":1,"canonicalText":"起對曰：「暴寇之來，必慮其強，善守勿應。","chunks":[["起對曰：「暴寇之來，必慮其強，善守勿應。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-2","passageId":"wu-zi_ch-5_p-10","order":2,"canonicalText":"彼將暮去，其裝必重，其心必恐，還退務速，必有不屬。","chunks":[["彼將暮去，其裝必重，其心必恐，還退務速，必有不屬。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-3","passageId":"wu-zi_ch-5_p-10","order":3,"canonicalText":"追而擊之，其兵可覆。","chunks":[["追而擊之，其兵可覆。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-4","passageId":"wu-zi_ch-5_p-10","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-1","passageId":"wu-zi_ch-5_p-11","order":1,"canonicalText":"吳子曰：「凡攻敵圍城之道，城邑既破，各入其宮。","chunks":[["吳子曰：「凡攻敵圍城之道，城邑既破，各入其宮。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-2","passageId":"wu-zi_ch-5_p-11","order":2,"canonicalText":"御其祿秩，收其器物。","chunks":[["御其祿秩，收其器物。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-3","passageId":"wu-zi_ch-5_p-11","order":3,"canonicalText":"軍之所至，無刊其木、發其屋、取其粟、殺其六畜、燔其積聚，示民無殘心。","chunks":[["軍之所至，無刊其木、發其屋、取其粟、殺其六畜、燔其積聚，示民無殘心。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-4","passageId":"wu-zi_ch-5_p-11","order":4,"canonicalText":"其有請降，許而安之。","chunks":[["其有請降，許而安之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-5","passageId":"wu-zi_ch-5_p-11","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-1","passageId":"wu-zi_ch-6_p-1","order":1,"canonicalText":"武侯問曰：「嚴刑明賞，足以勝乎？","chunks":[["武侯問曰：「嚴刑明賞，足以勝乎？","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-2","passageId":"wu-zi_ch-6_p-1","order":2,"canonicalText":"」起對曰：「嚴明之事，臣不能悉。","chunks":[["」起對曰：「嚴明之事，臣不能悉。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-3","passageId":"wu-zi_ch-6_p-1","order":3,"canonicalText":"雖然，非所恃也。","chunks":[["雖然，非所恃也。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-4","passageId":"wu-zi_ch-6_p-1","order":4,"canonicalText":"夫發號布令而人樂聞，興師動眾而人樂戰，交兵接刃而人樂死。","chunks":[["夫發號布令而人樂聞，興師動眾而人樂戰，交兵接刃而人樂死。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-5","passageId":"wu-zi_ch-6_p-1","order":5,"canonicalText":"此三者，人主之所恃也。","chunks":[["此三者，人主之所恃也。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-6","passageId":"wu-zi_ch-6_p-1","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-2_s-1","passageId":"wu-zi_ch-6_p-2","order":1,"canonicalText":"武侯曰：「致之奈何？","chunks":[["武侯曰：「致之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-6_p-2_s-2","passageId":"wu-zi_ch-6_p-2","order":2,"canonicalText":"」對曰：「君舉有功而進饗之，無功而勵之。","chunks":[["」對曰：「君舉有功而進饗之，無功而勵之。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-2_s-3","passageId":"wu-zi_ch-6_p-2","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-1","passageId":"wu-zi_ch-6_p-3","order":1,"canonicalText":"於是武侯設坐廟廷為三行饗士大夫。","chunks":[["於是武侯設坐廟廷為三行饗士大夫。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-2","passageId":"wu-zi_ch-6_p-3","order":2,"canonicalText":"上功坐前行，餚席兼重器、上牢。","chunks":[["上功坐前行，餚席兼重器、上牢。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-3","passageId":"wu-zi_ch-6_p-3","order":3,"canonicalText":"次功坐中行，餚席器差減。","chunks":[["次功坐中行，餚席器差減。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-4","passageId":"wu-zi_ch-6_p-3","order":4,"canonicalText":"無功坐後行，餚席無重器。","chunks":[["無功坐後行，餚席無重器。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-5","passageId":"wu-zi_ch-6_p-3","order":5,"canonicalText":"饗畢而出，又頒賜有功者父母妻子於廟門外，亦以功為差。","chunks":[["饗畢而出，又頒賜有功者父母妻子於廟門外，亦以功為差。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-6","passageId":"wu-zi_ch-6_p-3","order":6,"canonicalText":"有死事之家，歲被使者勞賜其父母，著不忘於心。","chunks":[["有死事之家，歲被使者勞賜其父母，著不忘於心。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-7","passageId":"wu-zi_ch-6_p-3","order":7,"canonicalText":"行之三年，秦人興師，臨於西河，魏士聞之，不待吏令，介冑而奮擊之者以萬數。","chunks":[["行之三年，秦人興師，臨於西河，魏士聞之，不待吏令，介冑而奮擊之者以萬數。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-1","passageId":"wu-zi_ch-6_p-4","order":1,"canonicalText":"武侯召吳起而謂曰：「子前日之教行矣。","chunks":[["武侯召吳起而謂曰：「子前日之教行矣。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-2","passageId":"wu-zi_ch-6_p-4","order":2,"canonicalText":"」起對曰：「臣聞人有短長，氣有盛衰。","chunks":[["」起對曰：「臣聞人有短長，氣有盛衰。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-3","passageId":"wu-zi_ch-6_p-4","order":3,"canonicalText":"君試發無功者五萬人，臣請率以當之。","chunks":[["君試發無功者五萬人，臣請率以當之。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-4","passageId":"wu-zi_ch-6_p-4","order":4,"canonicalText":"脫其不勝，取笑於諸侯，失權於天下矣。","chunks":[["脫其不勝，取笑於諸侯，失權於天下矣。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-5","passageId":"wu-zi_ch-6_p-4","order":5,"canonicalText":"今使一死賊伏於曠野，千人追之，莫不梟視狼顧。","chunks":[["今使一死賊伏於曠野，千人追之，莫不梟視狼顧。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-6","passageId":"wu-zi_ch-6_p-4","order":6,"canonicalText":"何者？","chunks":[["何者？","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-7","passageId":"wu-zi_ch-6_p-4","order":7,"canonicalText":"忌其暴起而害己。","chunks":[["忌其暴起而害己。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-8","passageId":"wu-zi_ch-6_p-4","order":8,"canonicalText":"是以一人投命，足懼千夫。","chunks":[["是以一人投命，足懼千夫。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-9","passageId":"wu-zi_ch-6_p-4","order":9,"canonicalText":"今臣以五萬之眾，而為一死賊，率以討之，固難敵矣。","chunks":[["今臣以五萬之眾，而為一死賊，率以討之，固難敵矣。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-10","passageId":"wu-zi_ch-6_p-4","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-5_s-1","passageId":"wu-zi_ch-6_p-5","order":1,"canonicalText":"於是武侯從之，兼車五百乘，騎三千匹，而破秦五十萬眾，此勵士之功也。","chunks":[["於是武侯從之，兼車五百乘，騎三千匹，而破秦五十萬眾，此勵士之功也。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-1","passageId":"wu-zi_ch-6_p-6","order":1,"canonicalText":"先戰一日，吳起令三軍曰：「諸吏士當從受馳。","chunks":[["先戰一日，吳起令三軍曰：「諸吏士當從受馳。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-2","passageId":"wu-zi_ch-6_p-6","order":2,"canonicalText":"車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。","chunks":[["車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-3","passageId":"wu-zi_ch-6_p-6","order":3,"canonicalText":"」故戰之日，其令不煩而威震天下。","chunks":[["」故戰之日，其令不煩而威震天下。","zh-Hant"]]}]}') as WorkBundle
